insert into public.results (id,data,created_at) values ('3k9ceezxan','{"pct":95,"cityName":"洛阳","cityKey":"luoyang","conclusion":"洛阳：地下文物和低物价，城市节奏慢而稳。","situation":"你想住在一个有旧东西可看、走两步就有故事的地方。","portrait":{"text":"你要的是有东西可逛、慢一点、吃得好；能接受新东西少一点、夜里安静一点。这不是旅行偏好，是你打算长期住下去时，最先受不了和最先离不开的部分。","vector":{"PACE":67,"FOOD":67,"CULT":100,"TECH":33,"NAT":67,"NIGHT":33,"SHOP":33,"CLIM":33,"COST":67,"GREEN":67},"top":[{"name":"文化历史","score":100},{"name":"生活节奏","score":67},{"name":"美食多元","score":67}],"low":[{"name":"科技创新","score":33},{"name":"夜生活","score":33}]},"vector":{"PACE":67,"FOOD":67,"CULT":100,"TECH":33,"NAT":67,"NIGHT":33,"SHOP":33,"CLIM":33,"COST":67,"GREEN":67},"dimRows":[{"key":"PACE","name":"生活节奏","score":67,"cityScore":80,"gap":13,"label":"合拍","aligned":true,"tendency":"你想慢下来，时间要能还给自己","reality":"慢，古都生活成本低","verdict":"节奏对得上，你不用刻意调快或调慢。"},{"key":"FOOD","name":"美食多元","score":67,"cityScore":70,"gap":3,"label":"合拍","aligned":true,"tendency":"你把吃当成日常的重要部分，选择要多","reality":"水席、汤馆，价格低","verdict":"吃的选择够你换着来，日常不会腻。"},{"key":"CULT","name":"文化历史","score":100,"cityScore":88,"gap":12,"label":"合拍","aligned":true,"tendency":"你需要有旧东西可看，博物馆和老街是日常","reality":"龙门石窟、白马寺、洛阳博物馆，地下文物密集","verdict":"博物馆和老街就在日常半径里，周末不用规划。"},{"key":"TECH","name":"科技创新","score":33,"cityScore":35,"gap":2,"label":"合拍","aligned":true,"tendency":"你对科技无感，传统方式更踏实","reality":"装备制造与新材料，互联网少","verdict":"你不需要新东西，这里慢一点也无所谓。"},{"key":"NAT","name":"自然环境","score":67,"cityScore":62,"gap":5,"label":"合拍","aligned":true,"tendency":"你需要山、水、蓝天，出门就能碰到自然","reality":"洛河穿城，山地在一小时外","verdict":"山或水在通勤范围内，出门就能换气。"},{"key":"NIGHT","name":"夜生活","score":33,"cityScore":40,"gap":7,"label":"合拍","aligned":true,"tendency":"你晚上不出门，安静更重要","reality":"老城十字街夜市，规模中等","verdict":"你睡得早，这里收摊早正好。"},{"key":"SHOP","name":"购物消费","score":33,"cityScore":48,"gap":15,"label":"合拍","aligned":true,"tendency":"你很少逛街，够用就行","reality":"老城与涧西商圈，商业一般","verdict":"你买得少，这里的商业够日常。"},{"key":"CLIM","name":"气候偏好","score":33,"cityScore":45,"gap":12,"label":"合拍","aligned":true,"tendency":"你受得了冷，甚至喜欢四季分明","reality":"冬季干冷，夏季干热，春季风大","verdict":"你受得了冷，这里的冬天不算障碍。"},{"key":"COST","name":"居住成本","score":67,"cityScore":82,"gap":15,"label":"合拍","aligned":true,"tendency":"你要低开销，房租不能吃掉生活","reality":"市区一居 1300 左右，开销很低","verdict":"房租和日常开销都在你能接受的范围内。"},{"key":"GREEN","name":"城市绿化","score":67,"cityScore":62,"gap":5,"label":"合拍","aligned":true,"tendency":"你要树荫、公园和能走的路","reality":"绿化覆盖率约 40%，洛浦公园沿河","verdict":"树荫、公园和绿道是日常，不是周末项目。"}],"reasons":[{"title":"节奏与成本","text":"先说每天的时间感和开销。生活节奏：慢，古都生活成本低。节奏对得上，你不用刻意调快或调慢。居住成本：市区一居 1300 左右，开销很低。房租和日常开销都在你能接受的范围内。","dims":["PACE","COST"]},{"title":"吃、逛与夜晚","text":"再看日常的消费与夜晚。美食多元：水席、汤馆，价格低。吃的选择够你换着来，日常不会腻。购物消费：老城与涧西商圈，商业一般。你买得少，这里的商业够日常。夜生活：老城十字街夜市，规模中等。你睡得早，这里收摊早正好。","dims":["FOOD","SHOP","NIGHT"]},{"title":"文化、自然与绿地","text":"然后是能走能看的部分。文化历史：龙门石窟、白马寺、洛阳博物馆，地下文物密集。博物馆和老街就在日常半径里，周末不用规划。自然环境：洛河穿城，山地在一小时外。山或水在通勤范围内，出门就能换气。城市绿化：绿化覆盖率约 40%，洛浦公园沿河。树荫、公园和绿道是日常，不是周末项目。","dims":["CULT","NAT","GREEN"]},{"title":"科技与气候","text":"最后是效率与体感。科技创新：装备制造与新材料，互联网少。你不需要新东西，这里慢一点也无所谓。气候偏好：冬季干冷，夏季干热，春季风大。你受得了冷，这里的冬天不算障碍。","dims":["TECH","CLIM"]}],"tradeoffs":["夜生活与商业偏少","就业结构单一"],"secondary":[{"city":"济南","pct":91,"conclusion":"济南：泉水和大明湖撑起了日常，节奏不快。","reason":"和洛阳相比，科技感更强、夜生活更旺，但文化设施少一些。"},{"city":"拉萨","pct":91,"conclusion":"拉萨：文化浓度和天空都很极端，海拔是硬门槛。","reason":"和洛阳相比，自然更近、更慢，但更干冷。"},{"city":"西安","pct":89,"conclusion":"西安：历史和面食管够，气候和收入都不算友好。","reason":"和洛阳相比，夜生活更旺、科技感更强，但更快、更赶。"}],"reverse":{"city":"深圳","pct":66,"why":"科技创新：南山科技园、坂田、坪山，硬件与互联网密度全国最高（这里比你要的过头）文化历史：历史短，南头古城、大鹏所城规模小，博物馆数量有限（这里比你想要的弱）","alternatives":[{"city":"青岛","pct":88,"why":"和深圳相比，更慢、生活成本更低，但科技氛围淡一些。"},{"city":"哈尔滨","pct":88,"why":"和深圳相比，生活成本更低、更慢，但更干冷。"}]},"theoryPanel":[{"title":"城市规模决定选择的数量","text":"城市越大，餐饮、展览、演出、夜宵的种类越多；但同样的丰富度，也意味着更长的通勤和更高的房租。丰富和松弛很少同时免费。"},{"title":"气候是最难改的变量","text":"气候无法靠个人努力调整。冬季日照、夏季湿度、雨季长度，会长期影响睡眠、情绪和出门频率，是选城时最值得当硬指标的一项。"},{"title":"绿地与通勤决定日常松弛","text":"绿地率、公园密度、平均通勤时间，决定散步和发呆是日常还是周末特权。它们不显眼，却最直接影响每天的状态。"},{"title":"居住成本决定选择权","text":"成本低的城市，意味着你可以接受薪水更低但更喜欢的工作、更长的空窗期。成本高则要求收入持续向上，选择会被压缩。"}],"boundary":["题目为自编，未做心理测量学标准化检验；维度分是偏好刻度，不是能力或人格测评。","城市十维坐标基于公开统计与生活经验的方向性整理（气候、绿地率、夜经济、餐饮多样性、历史街区与博物馆密度、消费水平等），会随年份和片区变化。","十个维度独立计分，不做相互抵消：某一维的高分不能补另一维的明显错位，错位维度会单独列出并计入扣分。","匹配度是剖面接近程度，不是概率，也不代表搬过去一定过得好。","结果不构成迁移、购房、医疗或投资建议；具体片区的房租、通勤、气候体感仍需自行核实。"],"matchNote":"十维等权独立计分，任一维差距 ≥45 会单独扣分并压低匹配度上限，不用其他维度的高分抵消。"}'::jsonb,'2026-11-19 14:01:32+08') on conflict (id) do nothing;
insert into public.results (id,data,created_at) values ('3nrnduh2kt','{"pct":84,"typeId":4,"key":"hibernator","name":"供暖区冬日宅","tagline":"窗外零下二十度，屋里穿短袖吃冰棍。","chips":["干冷体质","室内派","低夜生活","四季分明","边界感"],"cities":[{"city":"北京","areas":"朝阳、海淀（非核心商圈的老社区）"},{"city":"西安","areas":"雁塔、碑林"},{"city":"沈阳","areas":"和平、沈河"},{"city":"青岛","areas":"市南、市北"},{"city":"大连","areas":"中山、西岗"}],"profile":["你的幸福感来自「室内」：暖气、厚被子、炖菜、窗上的冰花。","你不喜欢夜里出门。冬天九点以后街上没人，你不觉得孤独，反而觉得世界终于安静了。","你的社交是「预约制」的：提前三天约，到了就好好聊，聊完各回各家。","你受不了南方的湿冷，就像南方人受不了北方的干燥——这不是矫情，是身体。"],"why":"你的气候体质明确偏干冷，夜间需求低，社交半径中等。这类人最适合有供暖、四季分明、城市尺度大但生活节奏不算极端的北方城市。供暖不只是舒适问题，它重塑了整个冬季的生活方式：室内成为真正的生活主场，商场、书店、澡堂、火锅店承担了南方「街道」的功能。这也是为什么北方城市的夜生活集中在「店」里，而不是「街」上。","costs":["冬季社交会萎缩，日照变短带来的情绪低落是真实存在的（季节性情感障碍，SAD）。","城市活力有季节性，冬天和夏天像两座城。","南方朋友会觉得你「宅得离谱」，而你只是不想在零下十五度等一辆不来的公交。"],"unfit":["需要全年夜生活的人","对干燥、静电、暖气房缺氧敏感的人","想在冬天保持高频户外社交的人"],"theoryTitle":"光照、情绪与室内生活","theory":"Rosenthal 等人命名的季节性情感障碍（SAD），把「冬天心情差」从性格问题还原成了光照问题：日照缩短会影响褪黑素与血清素节律，让人嗜睡、低落、想吃碳水。这也是为什么供暖城市把生活重心搬进室内是理性的——你在用空间对抗季节。但代价同样真实：室内越舒服，你越不会出门，社交与活动量会随日照一起缩水。","share":"我的社交半径，等于我家暖气片的长度。","matchReason":"你的答卷里有两个信号特别明显：你在「气候体质」上得分较低（干冷体质，离不开暖气和厚被子），在「文化密度」上得分较低（独处就能自足）。北京恰好在这两件事上同时给出了回应——冬天室内二十度，被子是厚的那种，安静得能听见自己。供暖重塑了这座城市的冬天：生活发生在室内，而不是街上。。所以它未必是「最好的城市」，但它和你咬合得最紧。","cityName":"北京","night":{"label":"被迫夜猫","modifier":"自我消化型","prescription":"你习惯把情绪留到深夜。城市能给你的是空间，不是答案。"},"vector":{"N":58.3,"P":25.0,"O":50.0,"C":16.7,"K":37.5,"S":44.4,"M":22.2},"secondary":[{"name":"海边 Wi-Fi 游民","pct":79},{"name":"县城咖啡馆主理人","pct":78}],"reverse":{"name":"凌晨便利店诗人","pct":58,"city":"上海"},"migratory":false,"migratoryType":null,"theoryPanel":[{"title":"人-环境匹配（P-E Fit）","body":"行为是人与环境交互的函数。本测试只测「需求-供给」匹配：七个维度是七种需求，城市原型是七种供给组合。匹配度描述的是「像不像」，不是「会不会幸福」。"},{"title":"恢复性环境理论（ART）","body":"自然环境的「离开感、柔和魅力、范围感、兼容性」能恢复被城市消耗的定向注意力。它解释了为什么有人住得越偏反而越好。"},{"title":"通勤悖论","body":"人们系统性低估长通勤对幸福的侵蚀，且事后补偿往往不足。中国主要城市通勤监测报告也显示，极端通勤比重在城市间差异显著。"},{"title":"都市社会学","body":"齐美尔讲都市刺激与倦怠，沃斯讲规模、密度与异质性带来的匿名，费孝通讲熟人社会与差序格局，项飙讲「附近的消失」。"},{"title":"气候与情绪","body":"季节性情感障碍（SAD）与光照时长相关；湿热、干燥与室内热舒适也真实影响睡眠与情绪。气候不是矫情，是身体。"},{"title":"生活方式迁移","body":"为生活方式而非工作迁移，是真实且增长中的现象。它带来自由，也带来身份感与成本的长期拉扯。"}],"boundary":["自报偏好不等于真实适应：结果反映你「此刻的想象」，不反映长期适应。","适应力被低估：搬家 6–12 个月后情绪常回弹，无论去哪。","百分比不是概率：它是剖面相似度刻度，不是「87% 的人会幸福」。","生态谬误：同城不同区的差异，可能大于城市之间。","硬约束未纳入：户籍、家庭、行业、健康、婚育、房贷，往往比城市气质更能决定结果。","样本与工具偏差：自编题目，未做心理测量学标准化检验。"]}'::jsonb,'2026-11-19 13:03:15+08') on conflict (id) do nothing;
insert into public.results (id,data,created_at) values ('3q5kykqg8c','{"pct":84,"typeId":4,"key":"hibernator","name":"供暖区冬日宅","tagline":"窗外零下二十度，屋里穿短袖吃冰棍。","chips":["干冷体质","室内派","低夜生活","四季分明","边界感"],"cities":[{"city":"北京","areas":"朝阳、海淀（非核心商圈的老社区）"},{"city":"西安","areas":"雁塔、碑林"},{"city":"沈阳","areas":"和平、沈河"},{"city":"青岛","areas":"市南、市北"},{"city":"大连","areas":"中山、西岗"}],"profile":["你的幸福感来自「室内」：暖气、厚被子、炖菜、窗上的冰花。","你不喜欢夜里出门。冬天九点以后街上没人，你不觉得孤独，反而觉得世界终于安静了。","你的社交是「预约制」的：提前三天约，到了就好好聊，聊完各回各家。","你受不了南方的湿冷，就像南方人受不了北方的干燥——这不是矫情，是身体。"],"why":"你的气候体质明确偏干冷，夜间需求低，社交半径中等。这类人最适合有供暖、四季分明、城市尺度大但生活节奏不算极端的北方城市。供暖不只是舒适问题，它重塑了整个冬季的生活方式：室内成为真正的生活主场，商场、书店、澡堂、火锅店承担了南方「街道」的功能。这也是为什么北方城市的夜生活集中在「店」里，而不是「街」上。","costs":["冬季社交会萎缩，日照变短带来的情绪低落是真实存在的（季节性情感障碍，SAD）。","城市活力有季节性，冬天和夏天像两座城。","南方朋友会觉得你「宅得离谱」，而你只是不想在零下十五度等一辆不来的公交。"],"unfit":["需要全年夜生活的人","对干燥、静电、暖气房缺氧敏感的人","想在冬天保持高频户外社交的人"],"theoryTitle":"光照、情绪与室内生活","theory":"Rosenthal 等人命名的季节性情感障碍（SAD），把「冬天心情差」从性格问题还原成了光照问题：日照缩短会影响褪黑素与血清素节律，让人嗜睡、低落、想吃碳水。这也是为什么供暖城市把生活重心搬进室内是理性的——你在用空间对抗季节。但代价同样真实：室内越舒服，你越不会出门，社交与活动量会随日照一起缩水。","share":"我的社交半径，等于我家暖气片的长度。","matchReason":"你的答卷里有两个信号特别明显：你在「气候体质」上得分较低（干冷体质，离不开暖气和厚被子），在「文化密度」上得分较低（独处就能自足）。北京恰好在这两件事上同时给出了回应——冬天室内二十度，被子是厚的那种，安静得能听见自己。供暖重塑了这座城市的冬天：生活发生在室内，而不是街上。。所以它未必是「最好的城市」，但它和你咬合得最紧。","cityName":"北京","night":{"label":"被迫夜猫","modifier":"自我消化型","prescription":"你习惯把情绪留到深夜。城市能给你的是空间，不是答案。"},"vector":{"N":58.3,"P":25.0,"O":50.0,"C":16.7,"K":37.5,"S":44.4,"M":22.2},"secondary":[{"name":"海边 Wi-Fi 游民","pct":79},{"name":"县城咖啡馆主理人","pct":78}],"reverse":{"name":"凌晨便利店诗人","pct":58,"city":"上海"},"migratory":false,"migratoryType":null,"theoryPanel":[{"title":"人-环境匹配（P-E Fit）","body":"行为是人与环境交互的函数。本测试只测「需求-供给」匹配：七个维度是七种需求，城市原型是七种供给组合。匹配度描述的是「像不像」，不是「会不会幸福」。"},{"title":"恢复性环境理论（ART）","body":"自然环境的「离开感、柔和魅力、范围感、兼容性」能恢复被城市消耗的定向注意力。它解释了为什么有人住得越偏反而越好。"},{"title":"通勤悖论","body":"人们系统性低估长通勤对幸福的侵蚀，且事后补偿往往不足。中国主要城市通勤监测报告也显示，极端通勤比重在城市间差异显著。"},{"title":"都市社会学","body":"齐美尔讲都市刺激与倦怠，沃斯讲规模、密度与异质性带来的匿名，费孝通讲熟人社会与差序格局，项飙讲「附近的消失」。"},{"title":"气候与情绪","body":"季节性情感障碍（SAD）与光照时长相关；湿热、干燥与室内热舒适也真实影响睡眠与情绪。气候不是矫情，是身体。"},{"title":"生活方式迁移","body":"为生活方式而非工作迁移，是真实且增长中的现象。它带来自由，也带来身份感与成本的长期拉扯。"}],"boundary":["自报偏好不等于真实适应：结果反映你「此刻的想象」，不反映长期适应。","适应力被低估：搬家 6–12 个月后情绪常回弹，无论去哪。","百分比不是概率：它是剖面相似度刻度，不是「87% 的人会幸福」。","生态谬误：同城不同区的差异，可能大于城市之间。","硬约束未纳入：户籍、家庭、行业、健康、婚育、房贷，往往比城市气质更能决定结果。","样本与工具偏差：自编题目，未做心理测量学标准化检验。"]}'::jsonb,'2026-11-19 13:03:36+08') on conflict (id) do nothing;
insert into public.results (id,data,created_at) values ('6yc2289fa2','{"pct":80,"typeId":1,"key":"poet","name":"凌晨便利店诗人","tagline":"城市越大，我越晚睡，也越自由。","chips":["夜行型","高刺激","便利店依赖","城市动物","一个人但不孤独"],"cities":[{"city":"上海","areas":"静安、黄浦、长宁（中山公园—愚园路）"},{"city":"深圳","areas":"南山、福田（车公庙、购物公园）"},{"city":"广州","areas":"天河、越秀（体育西、东山口）"},{"city":"杭州","areas":"拱墅、西湖区（武林、黄龙）"}],"profile":["你的一天从晚上十点开始。白天是义务，夜里才是自己的。","你能在 24 小时便利店里找到一种奇怪的归属感：关东煮的热气、收银员那句「需要袋子吗」、玻璃窗外的车流。","你怕的不是孤独，是无聊。你需要城市一直亮着，来证明你也没睡。","你的微信置顶有三个人，但你深夜真正会拨出去的，是外卖软件。"],"why":"你需要的不只是「夜生活」，而是夜间供给的密度：便利店、宵夜、深夜书店、凌晨还能打到车。这种密度只在一线城市的核心城区成立，因为它是人口密度、商业租金、夜班人力三者共同撑起来的。同时你对异质性的容忍度高——街上的人越杂，你越自在。","costs":["房租会吃掉你夜里消费的自由——你以为你在享受城市，其实在给房东打工。","睡眠债是复利的。二十六岁能扛，三十二岁开始还。","关系会变浅。深夜的便利店很温暖，但它不会记得你。"],"unfit":["冬天八点街上就空了的北方小城","需要早起、且家里有老人小孩的作息","你对「人多」的耐受其实没有自己以为的那么高"],"theoryTitle":"齐美尔的都市精神生活","theory":"齐美尔在《大都市与精神生活》里说，都市用高频刺激和货币经济塑造出一种「矜持而厌倦」的人格：你必须对太多刺激保持麻木，才能活下去。你熟悉的那种「在人群里最自在、却也最容易累」，不是性格缺陷，而是都市性的典型代价。沃斯进一步指出，规模、密度与异质性会带来匿名与次级关系——这既是你的自由，也是你深夜想找人说句话时，手机翻不出人的原因。","share":"我不是睡不着，我是在等这座城市先睡。","matchReason":"你的答卷里有两个信号特别明显：你在「文化密度」上得分很高（需要持续的文化刺激），在「夜间节律」上得分很高（越晚越清醒，夜里需要城市还开着）。上海恰好在这两件事上同时给出了回应——每周都有演出和展览，凌晨两点还有便利店和夜班车。城市用密度喂养你，也用密度消耗你——这是同一件事。。所以它未必是「最好的城市」，但它和你咬合得最紧。","cityName":"上海","night":{"label":"夜行动物","modifier":"服务依赖型","prescription":"你的安全感来自「随时能点到」。外卖覆盖率和便利店密度，比房租更值得你研究。"},"vector":{"N":97.2,"P":54.2,"O":100.0,"C":25.0,"K":100.0,"S":66.7,"M":66.7},"secondary":[{"name":"新一线性价比信徒","pct":75},{"name":"末班地铁赶路人","pct":72}],"reverse":{"name":"森林边早睡者","pct":55,"city":"丽水"},"migratory":false,"migratoryType":null,"theoryPanel":[{"title":"人-环境匹配（P-E Fit）","body":"行为是人与环境交互的函数。本测试只测「需求-供给」匹配：七个维度是七种需求，城市原型是七种供给组合。匹配度描述的是「像不像」，不是「会不会幸福」。"},{"title":"恢复性环境理论（ART）","body":"自然环境的「离开感、柔和魅力、范围感、兼容性」能恢复被城市消耗的定向注意力。它解释了为什么有人住得越偏反而越好。"},{"title":"通勤悖论","body":"人们系统性低估长通勤对幸福的侵蚀，且事后补偿往往不足。中国主要城市通勤监测报告也显示，极端通勤比重在城市间差异显著。"},{"title":"都市社会学","body":"齐美尔讲都市刺激与倦怠，沃斯讲规模、密度与异质性带来的匿名，费孝通讲熟人社会与差序格局，项飙讲「附近的消失」。"},{"title":"气候与情绪","body":"季节性情感障碍（SAD）与光照时长相关；湿热、干燥与室内热舒适也真实影响睡眠与情绪。气候不是矫情，是身体。"},{"title":"生活方式迁移","body":"为生活方式而非工作迁移，是真实且增长中的现象。它带来自由，也带来身份感与成本的长期拉扯。"}],"boundary":["自报偏好不等于真实适应：结果反映你「此刻的想象」，不反映长期适应。","适应力被低估：搬家 6–12 个月后情绪常回弹，无论去哪。","百分比不是概率：它是剖面相似度刻度，不是「87% 的人会幸福」。","生态谬误：同城不同区的差异，可能大于城市之间。","硬约束未纳入：户籍、家庭、行业、健康、婚育、房贷，往往比城市气质更能决定结果。","样本与工具偏差：自编题目，未做心理测量学标准化检验。"]}'::jsonb,'2026-11-19 13:06:57+08') on conflict (id) do nothing;
insert into public.results (id,data,created_at) values ('7gpbt3qbu5','{"pct":79,"cityName":"沈阳","cityKey":"shenyang","conclusion":"你是沈阳型：要低成本、低门槛，先把日子稳住。","situation":"你要解决的不是「去哪闯」，而是「离家不远、又能站住」这道题。","areas":["和平 · 太原街","浑南 · 奥体","铁西 · 启工"],"vector":{"IND":33.3,"COST":100.0,"GATE":33.3,"PACE":33.3,"RISK":33.3,"FAM":100.0,"SETTLE":100.0},"dimRows":[{"key":"IND","name":"行业机会密度","score":33,"cityScore":50,"tendency":"不依赖行业数量，一份对口的工作就够","reality":"装备制造、汽车、军工和医疗为主，新兴行业岗位少。","verdict":"行业面不宽，但和你的要求对得上，不用硬挤。","label":"合拍","aligned":true},{"key":"COST","name":"起步成本","score":100,"cityScore":82,"tendency":"对房租和生活开销敏感，先要活得起","reality":"一居 1200–1800，合租 800–1200；生活成本全国最低一档。","verdict":"房租和日常开销在你的预算内，起薪低一点也能存下钱。","label":"合拍","aligned":true},{"key":"GATE","name":"进入门槛","score":33,"cityScore":45,"tendency":"更想绕开硬门槛，找一条能先进场的路","reality":"制造业和国企看学历与技能证书，整体门槛低；考编竞争激烈。","verdict":"门槛不高，你的背景够用，进场比较容易。","label":"合拍","aligned":true},{"key":"PACE","name":"节奏与抗压","score":33,"cityScore":45,"tendency":"不愿用身体换钱，通勤和加班都要可控","reality":"通勤 30–40 分钟，节奏慢，加班少。","verdict":"节奏慢，正合你意，时间能还给自己。","label":"合拍","aligned":true},{"key":"RISK","name":"风险与试错","score":33,"cityScore":38,"tendency":"需要确定性，先站稳再谈发展","reality":"生活成本极低，试错压力小；但岗位少，失败后选择有限。","verdict":"这里更看重稳定，你也不打算折腾，正好。","label":"合拍","aligned":true},{"key":"FAM","name":"家庭牵绊","score":100,"cityScore":72,"tendency":"需要离家近，家里的事要能搭把手","reality":"东北区域中心，省内高铁方便，父母期待就近发展的压力大。","verdict":"离家比你希望的要远，回一趟成本高。","label":"基本合拍","aligned":true},{"key":"SETTLE","name":"长期定居","score":100,"cityScore":70,"tendency":"在意落户、买房和长期安家","reality":"房价极低、落户容易，医疗教育资源集中，定居压力最小。","verdict":"定居门槛比你想要的更紧，更适合当积累履历的一站。","label":"基本合拍","aligned":true}],"reasons":["先看机会和门槛。装备制造、汽车、军工和医疗为主，新兴行业岗位少。制造业和国企看学历与技能证书，整体门槛低；考编竞争激烈。对你来说，行业面不宽但够用，门槛不高，进场容易。","再看成本和节奏。一居 1200–1800，合租 800–1200；生活成本全国最低一档。通勤 30–40 分钟，节奏慢，加班少。你的情况是：房租在你的预算内，节奏慢，正合你意。这里更看重稳定，你也不打算折腾，正好。","最后是家庭和定居。东北区域中心，省内高铁方便，父母期待就近发展的压力大。房价极低、落户容易，医疗教育资源集中，定居压力最小。对你来说，离家比你希望的要远，定居门槛比你想要的更紧。"],"industries":[{"name":"装备制造与汽车","path":"校招","note":"铁西和大东，机械、焊接、电气岗位多。"},{"name":"军工与航空","path":"校招 / 考编","note":"稳定，政审严格。"},{"name":"医疗与养老服务","path":"社招","note":"人口老龄化带来稳定需求。"}],"landing":["投递方向：机械、电气、焊接工艺、设备维护、医药销售。","房租区间：800–1500；月薪六千可存三千。","落脚片区：2 号线奥体，1 号线铁西。"],"costs":["薪资低，涨薪慢。","民营经济弱，行业选择少。","冬天漫长寒冷。"],"unfit":["想拿高薪的人","需要行业多样性的人","怕冷的人"],"secondary":[{"city":"昆明","pct":75,"conclusion":"你是昆明型：把生活质量和气候放在职业之前。"},{"city":"大理","pct":72,"conclusion":"你是大理型：要自己掌控节奏，但需要一份能远程的收入。"},{"city":"重庆","pct":66,"conclusion":"你是重庆型：要低成本的落脚点，也接受行业选择没那么宽。"}],"reverse":{"city":"深圳","pct":50,"why":"它和你冲突最大的是「家庭牵绊」和「起步成本」：移民城市，外省人一年回两三次家；广东本地人周末可回。南山一居 5500 起，城中村 1800–2800；房价收入比全国最高。","alternatives":[{"city":"广州","why":"一线机会，房租和节奏都低一档。"},{"city":"佛山","why":"制造业岗位多，广佛线可跨城通勤，成本再低三成。"}]},"theoryPanel":[{"title":"城市规模溢价","text":"大城市给同岗位开出更高工资，但同时把房租、通勤和竞争强度一起抬高。经济学上把这叫规模溢价：收入涨得快，成本涨得更快。所以「去大城市」本身不是答案，关键看你的起薪能不能跑赢房租。"},{"title":"厚劳动力市场","text":"岗位越密集，人和岗位的匹配效率越高，跳槽带来的涨薪也越明显。代价是你必须持续证明自己。对刚毕业和想转行的人，这层「匹配效率」往往比城市名气更重要。"},{"title":"房租与通勤的取舍","text":"在单中心城市模型里，住得越远房租越低、通勤越长，理性人会沿着这条线找平衡点。结果页给你的房租区间，就是按「房租不超过税后收入 30%」反推的。"},{"title":"落户与公共服务","text":"落户、买房资格、子女入学和医保，决定了一座城市能不能从「打工的地方」变成「生活的地方」。如果你在长期定居这一维得分高，这一项会比薪资更影响你的选择。"}],"boundary":["结果基于你自述的偏好，而不是对你能力的测评；同样的答案，换一种人生阶段可能有不同结论。","城市数据来自公开统计与生活经验的方向性整理，房租、通勤、薪资会随区域和时间波动，具体到片区仍需自行核实。","匹配度是七维剖面的接近程度，是刻度不是概率，也不代表你在这座城市一定能成功。","测试没有覆盖婚育、健康、签证、行业周期等个人约束，这些因素可能比得分更决定你的选择。","结果不构成求职、迁移、购房或投资建议。真正做决定前，建议先用一周时间实地住一住、投几份简历试试水。"]}'::jsonb,'2026-11-19 13:37:01+08') on conflict (id) do nothing;
insert into public.results (id,data,created_at) values ('863gwhkyck','{"pct":62,"cityName":"成都","cityKey":"chengdu","conclusion":"你是成都型：要机会，但拒绝把生活全部押给工作。","situation":"你要解决的不是「去哪闯」，而是「离家不远、又能站住」这道题。","areas":["高新 · 天府三街","武侯 · 桐梓林","成华 · 建设路"],"vector":{"IND":100.0,"COST":100.0,"GATE":100.0,"PACE":100.0,"RISK":100.0,"FAM":100.0,"SETTLE":100.0},"dimRows":[{"key":"IND","name":"行业机会密度","score":100,"cityScore":78,"tendency":"需要岗位密集的大市场，随时能换赛道","reality":"游戏、软件、电子信息、文创和医疗都有，但头部岗位数量只有一线的一半。","verdict":"行业面比你需要的窄，三年后可能撞到天花板。","label":"基本合拍","aligned":true},{"key":"COST","name":"起步成本","score":100,"cityScore":75,"tendency":"对房租和生活开销敏感，先要活得起","reality":"南门一居 2500–3500，二圈层 1500–2200；房租收入比在大城市里偏低。","verdict":"房租会吃掉你一大块收入，起步阶段要算得很细。","label":"基本合拍","aligned":true},{"key":"GATE","name":"进入门槛","score":100,"cityScore":65,"tendency":"愿意在硬门槛里竞争，学历和履历拿得出手","reality":"大厂分部卡学历，本地中小企业更看经验和稳定性；考编竞争激烈。","verdict":"这里更看经验和稳定性，你的硬背景优势不明显。","label":"基本合拍","aligned":true},{"key":"PACE","name":"节奏与抗压","score":100,"cityScore":62,"tendency":"能扛快节奏和加班，把前几年当投入","reality":"通勤 35–45 分钟，加班集中在游戏和互联网，整体比一线慢半拍。","verdict":"这里比你习惯的慢，可能觉得不够劲。","label":"需要适应","aligned":false},{"key":"RISK","name":"风险与试错","score":100,"cityScore":62,"tendency":"敢试错，能接受空窗和转行","reality":"生活成本低，空窗和转行都扛得住；但高薪岗位少，涨薪往往靠去一线。","verdict":"这里更奖励稳定，频繁跳槽会伤履历。","label":"需要适应","aligned":false},{"key":"FAM","name":"家庭牵绊","score":100,"cityScore":75,"tendency":"需要离家近，家里的事要能搭把手","reality":"西南区域中心，川渝家庭高铁 1–2 小时，父母来同住也容易。","verdict":"离家比你希望的要远，回一趟成本高。","label":"基本合拍","aligned":true},{"key":"SETTLE","name":"长期定居","score":100,"cityScore":68,"tendency":"在意落户、买房和长期安家","reality":"落户宽松、房价温和，医疗教育在西部最好，长期定居友好。","verdict":"定居门槛比你想要的更紧，更适合当积累履历的一站。","label":"基本合拍","aligned":true}],"reasons":["先看机会和门槛。游戏、软件、电子信息、文创和医疗都有，但头部岗位数量只有一线的一半。大厂分部卡学历，本地中小企业更看经验和稳定性；考编竞争激烈。对你来说，行业面比你需要的窄，这里更看经验，学历优势不明显。","再看成本和节奏。南门一居 2500–3500，二圈层 1500–2200；房租收入比在大城市里偏低。通勤 35–45 分钟，加班集中在游戏和互联网，整体比一线慢半拍。你的情况是：房租会吃掉一大块收入，节奏比你习惯的慢。这里更奖励稳定，频繁跳槽会伤履历。","最后是家庭和定居。西南区域中心，川渝家庭高铁 1–2 小时，父母来同住也容易。落户宽松、房价温和，医疗教育在西部最好，长期定居友好。对你来说，离家比你希望的要远，定居门槛比你想要的更紧。"],"industries":[{"name":"游戏与数字文创","path":"社招 / 校招","note":"天府软件园集中，看作品集。"},{"name":"电子信息与军工","path":"校招","note":"高新西区，工科对口，稳定性好。"},{"name":"医疗与生物医药","path":"社招","note":"温江和天府国际生物城，要求专业背景。"}],"landing":["投递方向：游戏策划或测试、软件实施、医药代表与临床相关，先投本地中型公司。","房租区间：南门合租 1500–2500，整租一居 2500–3500。","落脚片区：1 号线天府三街，4 号线万年场。"],"costs":["高薪岗位少，做到中层容易触顶。","夏天闷热，冬天阴冷潮湿。","本地圈子文化重，外来者需要时间融入。"],"unfit":["想在三年内冲到高薪的人","只做前沿研发的人","受不了阴天和潮湿的人"],"secondary":[{"city":"杭州","pct":61,"conclusion":"你是杭州型：能卷，但不肯卷到失去生活。"},{"city":"重庆","pct":60,"conclusion":"你是重庆型：要低成本的落脚点，也接受行业选择没那么宽。"},{"city":"武汉","pct":60,"conclusion":"你是武汉型：要区域中心的机会，也要可承受的起步成本。"}],"reverse":{"city":"大理","pct":50,"why":"它和你冲突最大的是「节奏与抗压」和「行业机会密度」：通勤 15–25 分钟，节奏全国最慢；办事效率低。文旅、民宿、咖啡和少量数字游民社区，几乎没有大型企业。","alternatives":[{"city":"昆明","why":"机会更多，气候相近，医疗更强。"},{"city":"成都","why":"远程工作友好，生活便利。"}]},"theoryPanel":[{"title":"城市规模溢价","text":"大城市给同岗位开出更高工资，但同时把房租、通勤和竞争强度一起抬高。经济学上把这叫规模溢价：收入涨得快，成本涨得更快。所以「去大城市」本身不是答案，关键看你的起薪能不能跑赢房租。"},{"title":"厚劳动力市场","text":"岗位越密集，人和岗位的匹配效率越高，跳槽带来的涨薪也越明显。代价是你必须持续证明自己。对刚毕业和想转行的人，这层「匹配效率」往往比城市名气更重要。"},{"title":"房租与通勤的取舍","text":"在单中心城市模型里，住得越远房租越低、通勤越长，理性人会沿着这条线找平衡点。结果页给你的房租区间，就是按「房租不超过税后收入 30%」反推的。"},{"title":"落户与公共服务","text":"落户、买房资格、子女入学和医保，决定了一座城市能不能从「打工的地方」变成「生活的地方」。如果你在长期定居这一维得分高，这一项会比薪资更影响你的选择。"}],"boundary":["结果基于你自述的偏好，而不是对你能力的测评；同样的答案，换一种人生阶段可能有不同结论。","城市数据来自公开统计与生活经验的方向性整理，房租、通勤、薪资会随区域和时间波动，具体到片区仍需自行核实。","匹配度是七维剖面的接近程度，是刻度不是概率，也不代表你在这座城市一定能成功。","测试没有覆盖婚育、健康、签证、行业周期等个人约束，这些因素可能比得分更决定你的选择。","结果不构成求职、迁移、购房或投资建议。真正做决定前，建议先用一周时间实地住一住、投几份简历试试水。"]}'::jsonb,'2026-11-19 13:39:22+08') on conflict (id) do nothing;
insert into public.results (id,data,created_at) values ('98y8b2hbzn','{"pct":95,"cityName":"洛阳","cityKey":"luoyang","conclusion":"洛阳：地下文物和低物价，城市节奏慢而稳。","situation":"你想住在一个有旧东西可看、走两步就有故事的地方。","portrait":{"text":"你要的是有东西可逛、慢一点、吃得好；能接受新东西少一点、夜里安静一点。这不是旅行偏好，是你打算长期住下去时，最先受不了和最先离不开的部分。","vector":{"PACE":67,"FOOD":67,"CULT":100,"TECH":33,"NAT":67,"NIGHT":33,"SHOP":33,"CLIM":33,"COST":67,"GREEN":67},"top":[{"name":"文化历史","score":100},{"name":"生活节奏","score":67},{"name":"美食多元","score":67}],"low":[{"name":"科技创新","score":33},{"name":"夜生活","score":33}]},"vector":{"PACE":67,"FOOD":67,"CULT":100,"TECH":33,"NAT":67,"NIGHT":33,"SHOP":33,"CLIM":33,"COST":67,"GREEN":67},"dimRows":[{"key":"PACE","name":"生活节奏","score":67,"cityScore":80,"gap":13,"label":"合拍","aligned":true,"tendency":"你想慢下来，时间要能还给自己","reality":"慢，古都生活成本低","verdict":"节奏对得上，你不用刻意调快或调慢。"},{"key":"FOOD","name":"美食多元","score":67,"cityScore":70,"gap":3,"label":"合拍","aligned":true,"tendency":"你把吃当成日常的重要部分，选择要多","reality":"水席、汤馆，价格低","verdict":"吃的选择够你换着来，日常不会腻。"},{"key":"CULT","name":"文化历史","score":100,"cityScore":88,"gap":12,"label":"合拍","aligned":true,"tendency":"你需要有旧东西可看，博物馆和老街是日常","reality":"龙门石窟、白马寺、洛阳博物馆，地下文物密集","verdict":"博物馆和老街就在日常半径里，周末不用规划。"},{"key":"TECH","name":"科技创新","score":33,"cityScore":35,"gap":2,"label":"合拍","aligned":true,"tendency":"你对科技无感，传统方式更踏实","reality":"装备制造与新材料，互联网少","verdict":"你不需要新东西，这里慢一点也无所谓。"},{"key":"NAT","name":"自然环境","score":67,"cityScore":62,"gap":5,"label":"合拍","aligned":true,"tendency":"你需要山、水、蓝天，出门就能碰到自然","reality":"洛河穿城，山地在一小时外","verdict":"山或水在通勤范围内，出门就能换气。"},{"key":"NIGHT","name":"夜生活","score":33,"cityScore":40,"gap":7,"label":"合拍","aligned":true,"tendency":"你晚上不出门，安静更重要","reality":"老城十字街夜市，规模中等","verdict":"你睡得早，这里收摊早正好。"},{"key":"SHOP","name":"购物消费","score":33,"cityScore":48,"gap":15,"label":"合拍","aligned":true,"tendency":"你很少逛街，够用就行","reality":"老城与涧西商圈，商业一般","verdict":"你买得少，这里的商业够日常。"},{"key":"CLIM","name":"气候偏好","score":33,"cityScore":45,"gap":12,"label":"合拍","aligned":true,"tendency":"你受得了冷，甚至喜欢四季分明","reality":"冬季干冷，夏季干热，春季风大","verdict":"你受得了冷，这里的冬天不算障碍。"},{"key":"COST","name":"居住成本","score":67,"cityScore":82,"gap":15,"label":"合拍","aligned":true,"tendency":"你要低开销，房租不能吃掉生活","reality":"市区一居 1300 左右，开销很低","verdict":"房租和日常开销都在你能接受的范围内。"},{"key":"GREEN","name":"城市绿化","score":67,"cityScore":62,"gap":5,"label":"合拍","aligned":true,"tendency":"你要树荫、公园和能走的路","reality":"绿化覆盖率约 40%，洛浦公园沿河","verdict":"树荫、公园和绿道是日常，不是周末项目。"}],"reasons":[{"title":"节奏与成本","text":"先说每天的时间感和开销。生活节奏：慢，古都生活成本低。节奏对得上，你不用刻意调快或调慢。居住成本：市区一居 1300 左右，开销很低。房租和日常开销都在你能接受的范围内。","dims":["PACE","COST"]},{"title":"吃、逛与夜晚","text":"再看日常的消费与夜晚。美食多元：水席、汤馆，价格低。吃的选择够你换着来，日常不会腻。购物消费：老城与涧西商圈，商业一般。你买得少，这里的商业够日常。夜生活：老城十字街夜市，规模中等。你睡得早，这里收摊早正好。","dims":["FOOD","SHOP","NIGHT"]},{"title":"文化、自然与绿地","text":"然后是能走能看的部分。文化历史：龙门石窟、白马寺、洛阳博物馆，地下文物密集。博物馆和老街就在日常半径里，周末不用规划。自然环境：洛河穿城，山地在一小时外。山或水在通勤范围内，出门就能换气。城市绿化：绿化覆盖率约 40%，洛浦公园沿河。树荫、公园和绿道是日常，不是周末项目。","dims":["CULT","NAT","GREEN"]},{"title":"科技与气候","text":"最后是效率与体感。科技创新：装备制造与新材料，互联网少。你不需要新东西，这里慢一点也无所谓。气候偏好：冬季干冷，夏季干热，春季风大。你受得了冷，这里的冬天不算障碍。","dims":["TECH","CLIM"]}],"tradeoffs":["夜生活与商业偏少","产业结构单一"],"secondary":[{"city":"济南","pct":91,"conclusion":"济南：泉水和大明湖撑起了日常，节奏不快。","reason":"和洛阳相比，科技感更强、夜生活更旺，但文化设施少一些。"},{"city":"拉萨","pct":90,"conclusion":"拉萨：文化浓度和天空都很极端，海拔是硬门槛。","reason":"和洛阳相比，自然更近、更慢，但更干冷。"},{"city":"西安","pct":89,"conclusion":"西安：历史和面食管够，气候不算友好。","reason":"和洛阳相比，夜生活更旺、科技感更强，但更快、更赶。"}],"reverse":{"city":"深圳","pct":52,"why":"科技创新：南山科技园、坂田、坪山，硬件与互联网密度全国最高（这里比你要的多）文化历史：历史短，南头古城、大鹏所城规模小，博物馆数量有限（这里比你想要的少）","alternatives":[{"city":"青岛","pct":88,"why":"和深圳相比，更慢、生活成本更低，但科技氛围淡一些。"},{"city":"哈尔滨","pct":87,"why":"和深圳相比，生活成本更低、更慢，但更干冷。"}]},"theoryPanel":[{"title":"城市规模决定选择的数量","text":"城市越大，餐饮、展览、演出、夜宵的种类越多；但同样的丰富度，也意味着更长的通勤和更高的房租。丰富和松弛很少同时免费。"},{"title":"气候是最难改的变量","text":"气候无法靠个人努力调整。冬季日照、夏季湿度、雨季长度，会长期影响睡眠、情绪和出门频率，是选城时最值得当硬指标的一项。"},{"title":"绿地与通勤决定日常松弛","text":"绿地率、公园密度、平均通勤时间，决定散步和发呆是日常还是周末特权。它们不显眼，却最直接影响每天的状态。"},{"title":"居住成本决定选择权","text":"成本低的城市，意味着你可以接受薪水更低但更喜欢的工作、更长的空窗期。成本高则要求收入持续向上，选择会被压缩。"}],"boundary":["题目为自编，未做心理测量学标准化检验；维度分是偏好刻度，不是能力或人格测评。","城市十维坐标基于公开统计与生活经验的方向性整理（气候、绿地率、夜经济、餐饮多样性、历史街区与博物馆密度、消费水平等），会随年份和片区变化。","十个维度独立计分，不做相互抵消：某一维的高分不能补另一维的明显错位，错位维度会单独列出并计入扣分。","匹配度是剖面接近程度，不是概率，也不代表搬过去一定过得好。","结果不构成迁移、购房、医疗或投资建议；具体片区的房租、通勤、气候体感仍需自行核实。"],"matchNote":"十维等权独立计分，任一维差距 ≥45 会单独扣分并压低匹配度上限，不用其他维度的高分抵消。"}'::jsonb,'2026-11-19 14:04:17+08') on conflict (id) do nothing;
insert into public.results (id,data,created_at) values ('9pwebznp6u','{"pct":62,"cityName":"成都","cityKey":"chengdu","conclusion":"你是成都型：要机会，但拒绝把生活全部押给工作。","situation":"你要解决的不是「去哪闯」，而是「离家不远、又能站住」这道题。","areas":["高新 · 天府三街","武侯 · 桐梓林","成华 · 建设路"],"vector":{"IND":100.0,"COST":100.0,"GATE":100.0,"PACE":100.0,"RISK":100.0,"FAM":100.0,"SETTLE":100.0},"dimRows":[{"key":"IND","name":"行业机会密度","score":100,"cityScore":78,"tendency":"需要岗位密集的大市场，随时能换赛道","reality":"游戏、软件、电子信息、文创和医疗都有，但头部岗位数量只有一线的一半。","verdict":"行业面比你需要的窄，三年后可能撞到天花板。","label":"基本合拍","aligned":true},{"key":"COST","name":"起步成本","score":100,"cityScore":75,"tendency":"对房租和生活开销敏感，先要活得起","reality":"南门一居 2500–3500，二圈层 1500–2200；房租收入比在大城市里偏低。","verdict":"房租会吃掉你一大块收入，起步阶段要算得很细。","label":"基本合拍","aligned":true},{"key":"GATE","name":"进入门槛","score":100,"cityScore":65,"tendency":"愿意在硬门槛里竞争，学历和履历拿得出手","reality":"大厂分部卡学历，本地中小企业更看经验和稳定性；考编竞争激烈。","verdict":"这里更看经验和稳定性，你的硬背景优势不明显。","label":"基本合拍","aligned":true},{"key":"PACE","name":"节奏与抗压","score":100,"cityScore":62,"tendency":"能扛快节奏和加班，把前几年当投入","reality":"通勤 35–45 分钟，加班集中在游戏和互联网，整体比一线慢半拍。","verdict":"这里比你习惯的慢，可能觉得不够劲。","label":"需要适应","aligned":false},{"key":"RISK","name":"风险与试错","score":100,"cityScore":62,"tendency":"敢试错，能接受空窗和转行","reality":"生活成本低，空窗和转行都扛得住；但高薪岗位少，涨薪往往靠去一线。","verdict":"这里更奖励稳定，频繁跳槽会伤履历。","label":"需要适应","aligned":false},{"key":"FAM","name":"家庭牵绊","score":100,"cityScore":75,"tendency":"需要离家近，家里的事要能搭把手","reality":"西南区域中心，川渝家庭高铁 1–2 小时，父母来同住也容易。","verdict":"离家比你希望的要远，回一趟成本高。","label":"基本合拍","aligned":true},{"key":"SETTLE","name":"长期定居","score":100,"cityScore":68,"tendency":"在意落户、买房和长期安家","reality":"落户宽松、房价温和，医疗教育在西部最好，长期定居友好。","verdict":"定居门槛比你想要的更紧，更适合当积累履历的一站。","label":"基本合拍","aligned":true}],"reasons":["先看机会和门槛。游戏、软件、电子信息、文创和医疗都有，但头部岗位数量只有一线的一半。大厂分部卡学历，本地中小企业更看经验和稳定性；考编竞争激烈。对你来说，行业面比你需要的窄，这里更看经验，学历优势不明显。","再看成本和节奏。南门一居 2500–3500，二圈层 1500–2200；房租收入比在大城市里偏低。通勤 35–45 分钟，加班集中在游戏和互联网，整体比一线慢半拍。你的情况是：房租会吃掉一大块收入，节奏比你习惯的慢。这里更奖励稳定，频繁跳槽会伤履历。","最后是家庭和定居。西南区域中心，川渝家庭高铁 1–2 小时，父母来同住也容易。落户宽松、房价温和，医疗教育在西部最好，长期定居友好。对你来说，离家比你希望的要远，定居门槛比你想要的更紧。"],"industries":[{"name":"游戏与数字文创","path":"社招 / 校招","note":"天府软件园集中，看作品集。"},{"name":"电子信息与军工","path":"校招","note":"高新西区，工科对口，稳定性好。"},{"name":"医疗与生物医药","path":"社招","note":"温江和天府国际生物城，要求专业背景。"}],"landing":["投递方向：游戏策划或测试、软件实施、医药代表与临床相关，先投本地中型公司。","房租区间：南门合租 1500–2500，整租一居 2500–3500。","落脚片区：1 号线天府三街，4 号线万年场。"],"costs":["高薪岗位少，做到中层容易触顶。","夏天闷热，冬天阴冷潮湿。","本地圈子文化重，外来者需要时间融入。"],"unfit":["想在三年内冲到高薪的人","只做前沿研发的人","受不了阴天和潮湿的人"],"secondary":[{"city":"杭州","pct":61,"conclusion":"你是杭州型：能卷，但不肯卷到失去生活。"},{"city":"重庆","pct":60,"conclusion":"你是重庆型：要低成本的落脚点，也接受行业选择没那么宽。"},{"city":"武汉","pct":60,"conclusion":"你是武汉型：要区域中心的机会，也要可承受的起步成本。"}],"reverse":{"city":"大理","pct":50,"why":"它和你冲突最大的是「节奏与抗压」和「行业机会密度」：通勤 15–25 分钟，节奏全国最慢；办事效率低。文旅、民宿、咖啡和少量数字游民社区，几乎没有大型企业。","alternatives":[{"city":"昆明","why":"机会更多，气候相近，医疗更强。"},{"city":"成都","why":"远程工作友好，生活便利。"}]},"theoryPanel":[{"title":"城市规模溢价","text":"大城市给同岗位开出更高工资，但同时把房租、通勤和竞争强度一起抬高。经济学上把这叫规模溢价：收入涨得快，成本涨得更快。所以「去大城市」本身不是答案，关键看你的起薪能不能跑赢房租。"},{"title":"厚劳动力市场","text":"岗位越密集，人和岗位的匹配效率越高，跳槽带来的涨薪也越明显。代价是你必须持续证明自己。对刚毕业和想转行的人，这层「匹配效率」往往比城市名气更重要。"},{"title":"房租与通勤的取舍","text":"在单中心城市模型里，住得越远房租越低、通勤越长，理性人会沿着这条线找平衡点。结果页给你的房租区间，就是按「房租不超过税后收入 30%」反推的。"},{"title":"落户与公共服务","text":"落户、买房资格、子女入学和医保，决定了一座城市能不能从「打工的地方」变成「生活的地方」。如果你在长期定居这一维得分高，这一项会比薪资更影响你的选择。"}],"boundary":["结果基于你自述的偏好，而不是对你能力的测评；同样的答案，换一种人生阶段可能有不同结论。","城市数据来自公开统计与生活经验的方向性整理，房租、通勤、薪资会随区域和时间波动，具体到片区仍需自行核实。","匹配度是七维剖面的接近程度，是刻度不是概率，也不代表你在这座城市一定能成功。","测试没有覆盖婚育、健康、签证、行业周期等个人约束，这些因素可能比得分更决定你的选择。","结果不构成求职、迁移、购房或投资建议。真正做决定前，建议先用一周时间实地住一住、投几份简历试试水。"]}'::jsonb,'2026-11-19 13:26:20+08') on conflict (id) do nothing;
insert into public.results (id,data,created_at) values ('aymhgdffms','{"pct":85,"cityName":"成都","cityKey":"chengdu","conclusion":"成都：便宜、好吃、慢，代价是阴天多、机会面窄。","situation":"你现在要的不是一份城市榜单，而是一个能慢下来、也不用太拼命的地方。","portrait":{"text":"你要的是慢一点、吃得好、有东西可逛。这不是旅行偏好，是你打算长期住下去时，最先受不了和最先离不开的部分。","vector":{"PACE":100,"FOOD":100,"CULT":100,"TECH":100,"NAT":100,"NIGHT":100,"SHOP":100,"CLIM":100,"COST":100,"GREEN":100},"top":[{"name":"生活节奏","score":100},{"name":"美食多元","score":100},{"name":"文化历史","score":100}],"low":[]},"vector":{"PACE":100,"FOOD":100,"CULT":100,"TECH":100,"NAT":100,"NIGHT":100,"SHOP":100,"CLIM":100,"COST":100,"GREEN":100},"dimRows":[{"key":"PACE","name":"生活节奏","score":100,"cityScore":82,"gap":18,"label":"基本合拍","aligned":true,"tendency":"你想慢下来，时间要能还给自己","reality":"茶馆与公园密度高，下午三点街上仍有人坐着","verdict":"你会觉得这里太赶，得自己划出下班后的时间。"},{"key":"FOOD","name":"美食多元","score":100,"cityScore":95,"gap":5,"label":"合拍","aligned":true,"tendency":"你把吃当成日常的重要部分，选择要多","reality":"川菜核心，火锅、串串、小吃层级完整，价格低","verdict":"吃的选择够你换着来，日常不会腻。"},{"key":"CULT","name":"文化历史","score":100,"cityScore":82,"gap":18,"label":"基本合拍","aligned":true,"tendency":"你需要有旧东西可看，博物馆和老街是日常","reality":"武侯祠、杜甫草堂、金沙遗址，多数博物馆免费","verdict":"你想看的这里不够，得出城或接受线上看展。"},{"key":"TECH","name":"科技创新","score":100,"cityScore":70,"gap":30,"label":"基本合拍","aligned":true,"tendency":"你喜欢新东西，办事效率要高","reality":"天府软件园、高新区，游戏与电子信息集中","verdict":"这里的效率跟不上你，很多事要人工跑。"},{"key":"NAT","name":"自然环境","score":100,"cityScore":72,"gap":28,"label":"基本合拍","aligned":true,"tendency":"你需要山、水、蓝天，出门就能碰到自然","reality":"西岭雪山两小时可达，龙泉山城市森林公园在东侧","verdict":"山水离你太远，周末要花半天在路上。"},{"key":"NIGHT","name":"夜生活","score":100,"cityScore":88,"gap":12,"label":"合拍","aligned":true,"tendency":"你的晚上才开始，需要城市还醒着","reality":"九眼桥、玉林、建设路，凌晨仍有串串和酒馆","verdict":"晚上十点后城市还醒着，你的作息不用改。"},{"key":"SHOP","name":"购物消费","score":100,"cityScore":80,"gap":20,"label":"基本合拍","aligned":true,"tendency":"你喜欢逛，品牌和商场要齐","reality":"春熙路、太古里，商业体密集，消费活跃","verdict":"你想买的东西这里不一定有，得靠网购。"},{"key":"CLIM","name":"气候偏好","score":100,"cityScore":70,"gap":30,"label":"基本合拍","aligned":true,"tendency":"你怕冷，喜欢温暖湿润","reality":"1 月均温 6℃，阴天多、日照少，湿度大","verdict":"这里比你想要的更冷或更干，冬天会难熬。"},{"key":"COST","name":"居住成本","score":100,"cityScore":72,"gap":28,"label":"基本合拍","aligned":true,"tendency":"你要低开销，房租不能吃掉生活","reality":"二环一居 2000-2800，日常开销低","verdict":"这里比你预期的贵，房租会吃掉一部分生活。"},{"key":"GREEN","name":"城市绿化","score":100,"cityScore":76,"gap":24,"label":"基本合拍","aligned":true,"tendency":"你要树荫、公园和能走的路","reality":"公园 1500 余座，龙泉山与锦江绿道成环","verdict":"绿地和公园比你要的少，散步要挑地方。"}],"reasons":[{"title":"节奏与成本","text":"先说每天的时间感和开销。生活节奏：茶馆与公园密度高，下午三点街上仍有人坐着。你会觉得这里太赶，得自己划出下班后的时间。居住成本：二环一居 2000-2800，日常开销低。这里比你预期的贵，房租会吃掉一部分生活。","dims":["PACE","COST"]},{"title":"吃、逛与夜晚","text":"再看日常的消费与夜晚。美食多元：川菜核心，火锅、串串、小吃层级完整，价格低。吃的选择够你换着来，日常不会腻。购物消费：春熙路、太古里，商业体密集，消费活跃。你想买的东西这里不一定有，得靠网购。夜生活：九眼桥、玉林、建设路，凌晨仍有串串和酒馆。晚上十点后城市还醒着，你的作息不用改。","dims":["FOOD","SHOP","NIGHT"]},{"title":"文化、自然与绿地","text":"然后是能走能看的部分。文化历史：武侯祠、杜甫草堂、金沙遗址，多数博物馆免费。你想看的这里不够，得出城或接受线上看展。自然环境：西岭雪山两小时可达，龙泉山城市森林公园在东侧。山水离你太远，周末要花半天在路上。城市绿化：公园 1500 余座，龙泉山与锦江绿道成环。绿地和公园比你要的少，散步要挑地方。","dims":["CULT","NAT","GREEN"]},{"title":"科技与气候","text":"最后是效率与体感。科技创新：天府软件园、高新区，游戏与电子信息集中。这里的效率跟不上你，很多事要人工跑。气候偏好：1 月均温 6℃，阴天多、日照少，湿度大。这里比你想要的更冷或更干，冬天会难熬。","dims":["TECH","CLIM"]}],"tradeoffs":["全年日照偏少，冬季阴冷","互联网之外的新经济公司有限"],"secondary":[{"city":"广州","pct":83,"conclusion":"广州：吃和夜宵接近满分，贵的东西比北上深便宜一截。","reason":"和成都相比，更暖湿、科技感更强，但更快、更赶。"},{"city":"重庆","pct":82,"conclusion":"重庆：夜景和辣味管够，夏天是真的热。","reason":"和成都相比，自然更近、更暖湿，但文化设施少一些。"},{"city":"长沙","pct":80,"conclusion":"长沙：夜宵和房价都很友好，夏天热得直接。","reason":"和成都相比，生活成本更低、夜生活更旺，但文化设施少一些。"}],"reverse":{"city":"西宁","pct":42,"why":"气候偏好：夏季凉爽，冬季干冷，日照强（这里比你想要的更冷）夜生活：夜生活少（这里比你想要的更安静）","alternatives":[{"city":"杭州","pct":78,"why":"和西宁相比，科技感更强、更暖湿，但更快、更赶。"},{"city":"武汉","pct":77,"why":"和西宁相比，更暖湿、夜生活更旺，但更快、更赶。"}]},"theoryPanel":[{"title":"城市规模决定选择的数量","text":"城市越大，餐饮、展览、演出、夜宵的种类越多；但同样的丰富度，也意味着更长的通勤和更高的房租。丰富和松弛很少同时免费。"},{"title":"气候是最难改的变量","text":"气候无法靠个人努力调整。冬季日照、夏季湿度、雨季长度，会长期影响睡眠、情绪和出门频率，是选城时最值得当硬指标的一项。"},{"title":"绿地与通勤决定日常松弛","text":"绿地率、公园密度、平均通勤时间，决定散步和发呆是日常还是周末特权。它们不显眼，却最直接影响每天的状态。"},{"title":"居住成本决定选择权","text":"成本低的城市，意味着你可以接受薪水更低但更喜欢的工作、更长的空窗期。成本高则要求收入持续向上，选择会被压缩。"}],"boundary":["题目为自编，未做心理测量学标准化检验；维度分是偏好刻度，不是能力或人格测评。","城市十维坐标基于公开统计与生活经验的方向性整理（气候、绿地率、夜经济、餐饮多样性、历史街区与博物馆密度、消费水平等），会随年份和片区变化。","十个维度独立计分，不做相互抵消：某一维的高分不能补另一维的明显错位，错位维度会单独列出并计入扣分。","匹配度是剖面接近程度，不是概率，也不代表搬过去一定过得好。","结果不构成迁移、购房、医疗或投资建议；具体片区的房租、通勤、气候体感仍需自行核实。"],"matchNote":"十维等权独立计分，任一维差距 ≥45 会单独扣分并压低匹配度上限，不用其他维度的高分抵消。"}'::jsonb,'2026-11-19 14:06:27+08') on conflict (id) do nothing;
insert into public.results (id,data,created_at) values ('cpkr858zpm','{"pct":96,"cityName":"武汉","cityKey":"wuhan","conclusion":"你是武汉型：要区域中心的机会，也要可承受的起步成本。","situation":"你要解决的不是「去哪闯」，而是「离家不远、又能站住」这道题。","areas":["光谷 · 关山大道","武昌 · 中南路","汉阳 · 四新"],"vector":{"IND":66.7,"COST":66.7,"GATE":66.7,"PACE":66.7,"RISK":66.7,"FAM":66.7,"SETTLE":66.7},"dimRows":[{"key":"IND","name":"行业机会密度","score":67,"cityScore":76,"tendency":"需要岗位密集的大市场，随时能换赛道","reality":"光电子、汽车、生物医药、高校科研和互联网第二总部集中，中部岗位最全。","verdict":"岗位密度和你的预期对得上，换方向不用换城。","label":"合拍","aligned":true},{"key":"COST","name":"起步成本","score":67,"cityScore":65,"tendency":"对房租和生活开销敏感，先要活得起","reality":"光谷一居 2200–3200，合租 1300–2000；房租收入比低于沿海。","verdict":"房租和日常开销在你的预算内，起薪低一点也能存下钱。","label":"合拍","aligned":true},{"key":"GATE","name":"进入门槛","score":67,"cityScore":68,"tendency":"愿意在硬门槛里竞争，学历和履历拿得出手","reality":"高校多，校招竞争激烈；光谷企业看项目和实习，国企看学历。","verdict":"门槛和你的准备匹配，进正门不用绕道。","label":"合拍","aligned":true},{"key":"PACE","name":"节奏与抗压","score":67,"cityScore":72,"tendency":"能扛快节奏和加班，把前几年当投入","reality":"通勤 40–50 分钟，光谷早高峰堵；加班强度中等偏上。","verdict":"节奏快，但你能扛，前几年能换来位置。","label":"合拍","aligned":true},{"key":"RISK","name":"风险与试错","score":67,"cityScore":64,"tendency":"敢试错，能接受空窗和转行","reality":"产业门类全，转行相对容易；但高薪岗位仍少于一线。","verdict":"试错空间和你的胆量匹配，失败一次还有退路。","label":"合拍","aligned":true},{"key":"FAM","name":"家庭牵绊","score":67,"cityScore":70,"tendency":"需要离家近，家里的事要能搭把手","reality":"华中区域中心，高铁 2–3 小时覆盖周边省会，省内家庭周末可回。","verdict":"离家近，家里有事能搭把手，父母那边也好交代。","label":"合拍","aligned":true},{"key":"SETTLE","name":"长期定居","score":67,"cityScore":62,"tendency":"在意落户、买房和长期安家","reality":"落户宽松，房价中等，高校和医院资源强，定居性价比高。","verdict":"落户、房价和公共服务都支持你长期待下去。","label":"合拍","aligned":true}],"reasons":["先看机会和门槛。光电子、汽车、生物医药、高校科研和互联网第二总部集中，中部岗位最全。高校多，校招竞争激烈；光谷企业看项目和实习，国企看学历。对你来说，岗位密度和你的预期对得上，门槛和你的准备匹配。","再看成本和节奏。光谷一居 2200–3200，合租 1300–2000；房租收入比低于沿海。通勤 40–50 分钟，光谷早高峰堵；加班强度中等偏上。你的情况是：房租在你的预算内，节奏快但你能扛。试错空间和你的胆量匹配，失败一次还有退路。","最后是家庭和定居。华中区域中心，高铁 2–3 小时覆盖周边省会，省内家庭周末可回。落户宽松，房价中等，高校和医院资源强，定居性价比高。对你来说，离家近，能照应，落户和房价支持长期待下去。"],"industries":[{"name":"光电子与通信","path":"校招 / 社招","note":"光谷集中，对口工科，项目经验重要。"},{"name":"汽车与新能源","path":"校招","note":"经开区与蔡甸，制造和研发岗都有。"},{"name":"生物医药","path":"社招","note":"光谷生物城，要求专业背景。"}],"landing":["投递方向：光电或通信工程师、汽车电子、医药注册与临床。","房租区间：光谷合租 1300–2000，整租 2200–3200。","落脚片区：2 号线光谷段、11 号线。"],"costs":["光谷早高峰拥堵，通勤时间不稳定。","夏季酷热，湿度高。","高薪岗位集中在少数行业。"],"unfit":["追求一线薪资的人","受不了夏天高温的人","需要文娱产业的人"],"secondary":[{"city":"西安","pct":94,"conclusion":"你是西安型：要门槛可控的稳定岗位，也接受薪资不会太高。"},{"city":"成都","pct":93,"conclusion":"你是成都型：要机会，但拒绝把生活全部押给工作。"},{"city":"长沙","pct":92,"conclusion":"你是长沙型：要能攒下钱，也要离家不太远。"}],"reverse":{"city":"深圳","pct":61,"why":"它和你冲突最大的是「家庭牵绊」和「起步成本」：移民城市，外省人一年回两三次家；广东本地人周末可回。南山一居 5500 起，城中村 1800–2800；房价收入比全国最高。","alternatives":[{"city":"广州","why":"一线机会，房租和节奏都低一档。"},{"city":"佛山","why":"制造业岗位多，广佛线可跨城通勤，成本再低三成。"}]},"theoryPanel":[{"title":"城市规模溢价","text":"大城市给同岗位开出更高工资，但同时把房租、通勤和竞争强度一起抬高。经济学上把这叫规模溢价：收入涨得快，成本涨得更快。所以「去大城市」本身不是答案，关键看你的起薪能不能跑赢房租。"},{"title":"厚劳动力市场","text":"岗位越密集，人和岗位的匹配效率越高，跳槽带来的涨薪也越明显。代价是你必须持续证明自己。对刚毕业和想转行的人，这层「匹配效率」往往比城市名气更重要。"},{"title":"房租与通勤的取舍","text":"在单中心城市模型里，住得越远房租越低、通勤越长，理性人会沿着这条线找平衡点。结果页给你的房租区间，就是按「房租不超过税后收入 30%」反推的。"},{"title":"落户与公共服务","text":"落户、买房资格、子女入学和医保，决定了一座城市能不能从「打工的地方」变成「生活的地方」。如果你在长期定居这一维得分高，这一项会比薪资更影响你的选择。"}],"boundary":["结果基于你自述的偏好，而不是对你能力的测评；同样的答案，换一种人生阶段可能有不同结论。","城市数据来自公开统计与生活经验的方向性整理，房租、通勤、薪资会随区域和时间波动，具体到片区仍需自行核实。","匹配度是七维剖面的接近程度，是刻度不是概率，也不代表你在这座城市一定能成功。","测试没有覆盖婚育、健康、签证、行业周期等个人约束，这些因素可能比得分更决定你的选择。","结果不构成求职、迁移、购房或投资建议。真正做决定前，建议先用一周时间实地住一住、投几份简历试试水。"]}'::jsonb,'2026-11-19 13:25:28+08') on conflict (id) do nothing;
insert into public.results (id,data,created_at) values ('d8a4w9vd3a','{"pct":88,"cityName":"深圳","cityKey":"shenzhen","conclusion":"深圳：山海和效率都在线，历史薄、房价高。","situation":"你要的不是景点，是下班以后还有地方可去。","portrait":{"text":"你要的是吃得好、新东西跟得上、夜里有的玩；能接受节奏快一点、山水远一点。这不是旅行偏好，是你打算长期住下去时，最先受不了和最先离不开的部分。","vector":{"PACE":0,"FOOD":100,"CULT":67,"TECH":100,"NAT":33,"NIGHT":100,"SHOP":100,"CLIM":100,"COST":33,"GREEN":67},"top":[{"name":"美食多元","score":100},{"name":"科技创新","score":100},{"name":"夜生活","score":100}],"low":[{"name":"生活节奏","score":0},{"name":"自然环境","score":33}]},"vector":{"PACE":0,"FOOD":100,"CULT":67,"TECH":100,"NAT":33,"NIGHT":100,"SHOP":100,"CLIM":100,"COST":33,"GREEN":67},"dimRows":[{"key":"PACE","name":"生活节奏","score":0,"cityScore":35,"gap":35,"label":"需要适应","aligned":false,"tendency":"你习惯快节奏，闲下来反而不安","reality":"平均通勤约 36 分钟，但加班普遍，写字楼夜间灯火密度高","verdict":"这里节奏偏快，你也不算抗拒，勉强能对上。"},{"key":"FOOD","name":"美食多元","score":100,"cityScore":82,"gap":18,"label":"基本合拍","aligned":true,"tendency":"你把吃当成日常的重要部分，选择要多","reality":"移民城市，潮汕菜、湘菜、川菜与东南亚菜并存，本地菜薄","verdict":"你想吃的这里给不全，得降低预期或自己找。"},{"key":"CULT","name":"文化历史","score":67,"cityScore":45,"gap":22,"label":"基本合拍","aligned":true,"tendency":"你需要有旧东西可看，博物馆和老街是日常","reality":"历史短，南头古城、大鹏所城规模小，博物馆数量有限","verdict":"你想看的这里不够，得出城或接受线上看展。"},{"key":"TECH","name":"科技创新","score":100,"cityScore":95,"gap":5,"label":"合拍","aligned":true,"tendency":"你喜欢新东西，办事效率要高","reality":"南山科技园、坂田、坪山，硬件与互联网密度全国最高","verdict":"办事效率和新东西的密度都合你的习惯。"},{"key":"NAT","name":"自然环境","score":33,"cityScore":65,"gap":32,"label":"需要适应","aligned":false,"tendency":"你生活在室内，自然景观看得少也没关系","reality":"海岸线 260 公里，梧桐山在城内，周末去海边一小时","verdict":"自然资源比你要的多，周末不去也不亏。"},{"key":"NIGHT","name":"夜生活","score":100,"cityScore":82,"gap":18,"label":"基本合拍","aligned":true,"tendency":"你的晚上才开始，需要城市还醒着","reality":"夜宵与酒吧集中在福田、南山，营业时间长","verdict":"你想出门的时候，这里已经安静了。"},{"key":"SHOP","name":"购物消费","score":100,"cityScore":85,"gap":15,"label":"合拍","aligned":true,"tendency":"你喜欢逛，品牌和商场要齐","reality":"万象城、海岸城等大型商业体密集，品牌新","verdict":"品牌和商场密度对得上你的逛街习惯。"},{"key":"CLIM","name":"气候偏好","score":100,"cityScore":86,"gap":14,"label":"合拍","aligned":true,"tendency":"你怕冷，喜欢温暖湿润","reality":"1 月均温 15℃，夏季长，7-9 月台风影响","verdict":"气候体感合你，冬天不用硬扛。"},{"key":"COST","name":"居住成本","score":33,"cityScore":28,"gap":5,"label":"合拍","aligned":true,"tendency":"你能接受高成本，换来地段和便利","reality":"南山一居 5500 起，城中村 1800-2800，房价高","verdict":"你愿意为地段多付，这里的价格你扛得住。"},{"key":"GREEN","name":"城市绿化","score":67,"cityScore":78,"gap":11,"label":"合拍","aligned":true,"tendency":"你要树荫、公园和能走的路","reality":"公园 1200 余座，绿化覆盖率约 45%，绿道总长全国前列","verdict":"树荫、公园和绿道是日常，不是周末项目。"}],"reasons":[{"title":"节奏与成本","text":"先说每天的时间感和开销。生活节奏：平均通勤约 36 分钟，但加班普遍，写字楼夜间灯火密度高。这里节奏偏快，你也不算抗拒，勉强能对上。居住成本：南山一居 5500 起，城中村 1800-2800，房价高。你愿意为地段多付，这里的价格你扛得住。","dims":["PACE","COST"]},{"title":"吃、逛与夜晚","text":"再看日常的消费与夜晚。美食多元：移民城市，潮汕菜、湘菜、川菜与东南亚菜并存，本地菜薄。你想吃的这里给不全，得降低预期或自己找。购物消费：万象城、海岸城等大型商业体密集，品牌新。品牌和商场密度对得上你的逛街习惯。夜生活：夜宵与酒吧集中在福田、南山，营业时间长。你想出门的时候，这里已经安静了。","dims":["FOOD","SHOP","NIGHT"]},{"title":"文化、自然与绿地","text":"然后是能走能看的部分。文化历史：历史短，南头古城、大鹏所城规模小，博物馆数量有限。你想看的这里不够，得出城或接受线上看展。自然环境：海岸线 260 公里，梧桐山在城内，周末去海边一小时。自然资源比你要的多，周末不去也不亏。城市绿化：公园 1200 余座，绿化覆盖率约 45%，绿道总长全国前列。树荫、公园和绿道是日常，不是周末项目。","dims":["CULT","NAT","GREEN"]},{"title":"科技与气候","text":"最后是效率与体感。科技创新：南山科技园、坂田、坪山，硬件与互联网密度全国最高。办事效率和新东西的密度都合你的习惯。气候偏好：1 月均温 15℃，夏季长，7-9 月台风影响。气候体感合你，冬天不用硬扛。","dims":["TECH","CLIM"]}],"tradeoffs":["房价与房租仅次于北京上海","城市年轻，文化沉淀少"],"secondary":[{"city":"上海","pct":84,"conclusion":"上海：把丰富度做到极致，但要用房租、通勤和拥挤去换。","reason":"和深圳相比，历史文博更密、商业更发达，但山水要跑远。"},{"city":"武汉","pct":79,"conclusion":"武汉：江湖气足、价格温和，夏天冬天都不好过。","reason":"和深圳相比，生活成本更低、历史文博更密，但科技氛围淡一些。"},{"city":"杭州","pct":78,"conclusion":"杭州：能卷，但西湖和绿道把生活留住了。","reason":"和深圳相比，历史文博更密、更慢，但更干冷。"}],"reverse":{"city":"西宁","pct":34,"why":"生活节奏：慢，高原城市节奏（这里比你要的更慢）气候偏好：夏季凉爽，冬季干冷，日照强（这里比你想要的更冷）","alternatives":[{"city":"广州","pct":70,"why":"和西宁相比，更暖湿、夜生活更旺，但更快、更赶。"},{"city":"北京","pct":69,"why":"和西宁相比，科技感更强、历史文博更密，但更快、更赶。"}]},"theoryPanel":[{"title":"城市规模决定选择的数量","text":"城市越大，餐饮、展览、演出、夜宵的种类越多；但同样的丰富度，也意味着更长的通勤和更高的房租。丰富和松弛很少同时免费。"},{"title":"气候是最难改的变量","text":"气候无法靠个人努力调整。冬季日照、夏季湿度、雨季长度，会长期影响睡眠、情绪和出门频率，是选城时最值得当硬指标的一项。"},{"title":"绿地与通勤决定日常松弛","text":"绿地率、公园密度、平均通勤时间，决定散步和发呆是日常还是周末特权。它们不显眼，却最直接影响每天的状态。"},{"title":"居住成本决定选择权","text":"成本低的城市，意味着你可以接受薪水更低但更喜欢的工作、更长的空窗期。成本高则要求收入持续向上，选择会被压缩。"}],"boundary":["题目为自编，未做心理测量学标准化检验；维度分是偏好刻度，不是能力或人格测评。","城市十维坐标基于公开统计与生活经验的方向性整理（气候、绿地率、夜经济、餐饮多样性、历史街区与博物馆密度、消费水平等），会随年份和片区变化。","十个维度独立计分，不做相互抵消：某一维的高分不能补另一维的明显错位，错位维度会单独列出并计入扣分。","匹配度是剖面接近程度，不是概率，也不代表搬过去一定过得好。","结果不构成迁移、购房、医疗或投资建议；具体片区的房租、通勤、气候体感仍需自行核实。"],"matchNote":"十维等权独立计分，任一维差距 ≥45 会单独扣分并压低匹配度上限，不用其他维度的高分抵消。"}'::jsonb,'2026-11-19 14:04:17+08') on conflict (id) do nothing;
insert into public.results (id,data,created_at) values ('df2znemetn','{"pct":80,"cityName":"兰州","cityKey":"lanzhou","conclusion":"兰州：一条黄河穿城，牛肉面和低成本撑起日常。","situation":"你要的是一个能长期待下去、日常不太费劲的地方。","portrait":{"text":"你要的是慢一点、有东西可逛；能接受绿地少一点、冬天冷一点。这不是旅行偏好，是你打算长期住下去时，最先受不了和最先离不开的部分。","vector":{"PACE":33,"FOOD":27,"CULT":33,"TECH":33,"NAT":20,"NIGHT":20,"SHOP":27,"CLIM":13,"COST":27,"GREEN":7},"top":[{"name":"生活节奏","score":33},{"name":"文化历史","score":33}],"low":[{"name":"城市绿化","score":7},{"name":"气候偏好","score":13}]},"vector":{"PACE":33,"FOOD":27,"CULT":33,"TECH":33,"NAT":20,"NIGHT":20,"SHOP":27,"CLIM":13,"COST":27,"GREEN":7},"dimRows":[{"key":"PACE","name":"生活节奏","score":33,"cityScore":80,"gap":47,"label":"明显错位","aligned":false,"tendency":"你习惯快节奏，闲下来反而不安","reality":"慢，黄河谷地城市","verdict":"这里比你要的还慢，日子会松，但办事也慢。"},{"key":"FOOD","name":"美食多元","score":27,"cityScore":70,"gap":43,"label":"需要适应","aligned":false,"tendency":"吃能对付，不太挑","reality":"牛肉面与西北菜，价格低","verdict":"这里的餐饮密度超过你的日常需求，算是余量。"},{"key":"CULT","name":"文化历史","score":33,"cityScore":45,"gap":12,"label":"合拍","aligned":true,"tendency":"你对历史文博没什么兴趣","reality":"甘肃省博、中山桥","verdict":"你对这些不执着，城市年轻也不影响你。"},{"key":"TECH","name":"科技创新","score":33,"cityScore":38,"gap":5,"label":"合拍","aligned":true,"tendency":"你对科技无感，传统方式更踏实","reality":"以石化与装备制造为主，数字化偏慢","verdict":"你不需要新东西，这里慢一点也无所谓。"},{"key":"NAT","name":"自然环境","score":20,"cityScore":45,"gap":25,"label":"基本合拍","aligned":true,"tendency":"你生活在室内，自然景观看得少也没关系","reality":"黄河穿城，南北两山","verdict":"自然资源比你要的多，周末不去也不亏。"},{"key":"NIGHT","name":"夜生活","score":20,"cityScore":40,"gap":20,"label":"基本合拍","aligned":true,"tendency":"你晚上不出门，安静更重要","reality":"夜市以正宁路为主","verdict":"夜里没什么可去，你也不出门，互不打扰。"},{"key":"SHOP","name":"购物消费","score":27,"cityScore":45,"gap":18,"label":"基本合拍","aligned":true,"tendency":"你很少逛街，够用就行","reality":"张掖路商圈","verdict":"商业比你要的发达，逛的选择多，花钱也快。"},{"key":"CLIM","name":"气候偏好","score":13,"cityScore":20,"gap":7,"label":"合拍","aligned":true,"tendency":"你受得了冷，甚至喜欢四季分明","reality":"干燥少雨，冬季冷，夏季凉爽","verdict":"你受得了冷，这里的冬天不算障碍。"},{"key":"COST","name":"居住成本","score":27,"cityScore":76,"gap":49,"label":"明显错位","aligned":false,"tendency":"你能接受高成本，换来地段和便利","reality":"市区一居 1300 左右，开销很低","verdict":"这里比你需要的更便宜，能存下钱。"},{"key":"GREEN","name":"城市绿化","score":7,"cityScore":50,"gap":43,"label":"需要适应","aligned":false,"tendency":"绿地多少你不敏感","reality":"绿化覆盖率约 33%，两山绿化工程","verdict":"绿化超过你的需求，算是白送的。"}],"reasons":[{"title":"节奏与成本","text":"先说每天的时间感和开销。生活节奏：慢，黄河谷地城市。这里比你要的还慢，日子会松，但办事也慢。居住成本：市区一居 1300 左右，开销很低。这里比你需要的更便宜，能存下钱。","dims":["PACE","COST"]},{"title":"吃、逛与夜晚","text":"再看日常的消费与夜晚。美食多元：牛肉面与西北菜，价格低。这里的餐饮密度超过你的日常需求，算是余量。购物消费：张掖路商圈。商业比你要的发达，逛的选择多，花钱也快。夜生活：夜市以正宁路为主。夜里没什么可去，你也不出门，互不打扰。","dims":["FOOD","SHOP","NIGHT"]},{"title":"文化、自然与绿地","text":"然后是能走能看的部分。文化历史：甘肃省博、中山桥。你对这些不执着，城市年轻也不影响你。自然环境：黄河穿城，南北两山。自然资源比你要的多，周末不去也不亏。城市绿化：绿化覆盖率约 33%，两山绿化工程。绿化超过你的需求，算是白送的。","dims":["CULT","NAT","GREEN"]},{"title":"科技与气候","text":"最后是效率与体感。科技创新：以石化与装备制造为主，数字化偏慢。你不需要新东西，这里慢一点也无所谓。气候偏好：干燥少雨，冬季冷，夏季凉爽。你受得了冷，这里的冬天不算障碍。","dims":["TECH","CLIM"]}],"tradeoffs":["河谷地形，空气扩散条件差","绿地率在省会里偏低"],"secondary":[{"city":"呼和浩特","pct":79,"conclusion":"呼和浩特：草原一小时可达，城市生活简单便宜。","reason":"和兰州相比，自然更近、绿化更好，但更干冷。"},{"city":"乌鲁木齐","pct":78,"conclusion":"乌鲁木齐：作息晚两小时，干燥、开阔、烤肉管够。","reason":"和兰州相比，自然更近、历史文博更密，但更干冷。"},{"city":"西宁","pct":77,"conclusion":"西宁：夏天不用空调，冬天干冷，是最凉爽的省会之一。","reason":"和兰州相比，自然更近、更慢，但吃的选择少一档。"}],"reverse":{"city":"成都","pct":36,"why":"城市绿化：公园 1500 余座，龙泉山与锦江绿道成环（这里比你要的多）美食多元：川菜核心，火锅、串串、小吃层级完整，价格低（这里比你要的多）","alternatives":[{"city":"银川","pct":76,"why":"和成都相比，生活成本更低，但晚上更早安静。"},{"city":"沈阳","pct":71,"why":"和成都相比，生活成本更低，但更干冷。"}]},"theoryPanel":[{"title":"城市规模决定选择的数量","text":"城市越大，餐饮、展览、演出、夜宵的种类越多；但同样的丰富度，也意味着更长的通勤和更高的房租。丰富和松弛很少同时免费。"},{"title":"气候是最难改的变量","text":"气候无法靠个人努力调整。冬季日照、夏季湿度、雨季长度，会长期影响睡眠、情绪和出门频率，是选城时最值得当硬指标的一项。"},{"title":"绿地与通勤决定日常松弛","text":"绿地率、公园密度、平均通勤时间，决定散步和发呆是日常还是周末特权。它们不显眼，却最直接影响每天的状态。"},{"title":"居住成本决定选择权","text":"成本低的城市，意味着你可以接受薪水更低但更喜欢的工作、更长的空窗期。成本高则要求收入持续向上，选择会被压缩。"}],"boundary":["题目为自编，未做心理测量学标准化检验；维度分是偏好刻度，不是能力或人格测评。","城市十维坐标基于公开统计与生活经验的方向性整理（气候、绿地率、夜经济、餐饮多样性、历史街区与博物馆密度、消费水平等），会随年份和片区变化。","十个维度独立计分，不做相互抵消：某一维的高分不能补另一维的明显错位，错位维度会单独列出并计入扣分。","匹配度是剖面接近程度，不是概率，也不代表搬过去一定过得好。","结果不构成迁移、购房、医疗或投资建议；具体片区的房租、通勤、气候体感仍需自行核实。"],"matchNote":"十维等权独立计分，任一维差距 ≥45 会单独扣分并压低匹配度上限，不用其他维度的高分抵消。"}'::jsonb,'2026-11-19 14:19:38+08') on conflict (id) do nothing;
insert into public.results (id,data,created_at) values ('fpy5cwztet','{"pct":80,"cityName":"武汉","cityKey":"wuhan","conclusion":"你是武汉型：要区域中心的机会，也要可承受的起步成本。","situation":"你还有试错的余地，关键是别把时间花在错的赛道上。","areas":["光谷 · 关山大道","武昌 · 中南路","汉阳 · 四新"],"vector":{"IND":66.7,"COST":66.7,"GATE":66.7,"PACE":66.7,"RISK":100.0,"FAM":33.3,"SETTLE":33.3},"dimRows":[{"key":"IND","name":"行业机会密度","score":67,"cityScore":76,"tendency":"需要岗位密集的大市场，随时能换赛道","reality":"光电子、汽车、生物医药、高校科研和互联网第二总部集中，中部岗位最全。","verdict":"岗位密度和你的预期对得上，换方向不用换城。","label":"合拍","aligned":true},{"key":"COST","name":"起步成本","score":67,"cityScore":65,"tendency":"对房租和生活开销敏感，先要活得起","reality":"光谷一居 2200–3200，合租 1300–2000；房租收入比低于沿海。","verdict":"房租和日常开销在你的预算内，起薪低一点也能存下钱。","label":"合拍","aligned":true},{"key":"GATE","name":"进入门槛","score":67,"cityScore":68,"tendency":"愿意在硬门槛里竞争，学历和履历拿得出手","reality":"高校多，校招竞争激烈；光谷企业看项目和实习，国企看学历。","verdict":"门槛和你的准备匹配，进正门不用绕道。","label":"合拍","aligned":true},{"key":"PACE","name":"节奏与抗压","score":67,"cityScore":72,"tendency":"能扛快节奏和加班，把前几年当投入","reality":"通勤 40–50 分钟，光谷早高峰堵；加班强度中等偏上。","verdict":"节奏快，但你能扛，前几年能换来位置。","label":"合拍","aligned":true},{"key":"RISK","name":"风险与试错","score":100,"cityScore":64,"tendency":"敢试错，能接受空窗和转行","reality":"产业门类全，转行相对容易；但高薪岗位仍少于一线。","verdict":"这里更奖励稳定，频繁跳槽会伤履历。","label":"需要适应","aligned":false},{"key":"FAM","name":"家庭牵绊","score":33,"cityScore":70,"tendency":"家庭牵绊小，可以去远一点的地方","reality":"华中区域中心，高铁 2–3 小时覆盖周边省会，省内家庭周末可回。","verdict":"这里离家更近，父母会更容易满意，但你可能觉得被看着。","label":"需要适应","aligned":false},{"key":"SETTLE","name":"长期定居","score":33,"cityScore":62,"tendency":"不急着定居，先看机会","reality":"落户宽松，房价中等，高校和医院资源强，定居性价比高。","verdict":"这里比你现在需要的更适合安家，但你未必想被绑住。","label":"基本合拍","aligned":true}],"reasons":["先看机会和门槛。光电子、汽车、生物医药、高校科研和互联网第二总部集中，中部岗位最全。高校多，校招竞争激烈；光谷企业看项目和实习，国企看学历。对你来说，岗位密度和你的预期对得上，门槛和你的准备匹配。","再看成本和节奏。光谷一居 2200–3200，合租 1300–2000；房租收入比低于沿海。通勤 40–50 分钟，光谷早高峰堵；加班强度中等偏上。你的情况是：房租在你的预算内，节奏快但你能扛。这里更奖励稳定，频繁跳槽会伤履历。","最后是家庭和定居。华中区域中心，高铁 2–3 小时覆盖周边省会，省内家庭周末可回。落户宽松，房价中等，高校和医院资源强，定居性价比高。对你来说，这里离家更近，这里比你现在需要的更适合安家。"],"industries":[{"name":"光电子与通信","path":"校招 / 社招","note":"光谷集中，对口工科，项目经验重要。"},{"name":"汽车与新能源","path":"校招","note":"经开区与蔡甸，制造和研发岗都有。"},{"name":"生物医药","path":"社招","note":"光谷生物城，要求专业背景。"}],"landing":["投递方向：光电或通信工程师、汽车电子、医药注册与临床。","房租区间：光谷合租 1300–2000，整租 2200–3200。","落脚片区：2 号线光谷段、11 号线。"],"costs":["光谷早高峰拥堵，通勤时间不稳定。","夏季酷热，湿度高。","高薪岗位集中在少数行业。"],"unfit":["追求一线薪资的人","受不了夏天高温的人","需要文娱产业的人"],"secondary":[{"city":"广州","pct":80,"conclusion":"你是广州型：要一线机会，也要能过日子的成本。"},{"city":"苏州","pct":78,"conclusion":"你是苏州型：要制造业和外企的稳定岗位，也想离上海不远。"},{"city":"西安","pct":78,"conclusion":"你是西安型：要门槛可控的稳定岗位，也接受薪资不会太高。"}],"reverse":{"city":"沈阳","pct":63,"why":"它和你冲突最大的是「风险与试错」和「家庭牵绊」：生活成本极低，试错压力小；但岗位少，失败后选择有限。东北区域中心，省内高铁方便，父母期待就近发展的压力大。","alternatives":[{"city":"天津","why":"岗位层次更高，高铁 2 小时。"},{"city":"青岛","why":"气候更温和，制造业相近。"}]},"theoryPanel":[{"title":"城市规模溢价","text":"大城市给同岗位开出更高工资，但同时把房租、通勤和竞争强度一起抬高。经济学上把这叫规模溢价：收入涨得快，成本涨得更快。所以「去大城市」本身不是答案，关键看你的起薪能不能跑赢房租。"},{"title":"厚劳动力市场","text":"岗位越密集，人和岗位的匹配效率越高，跳槽带来的涨薪也越明显。代价是你必须持续证明自己。对刚毕业和想转行的人，这层「匹配效率」往往比城市名气更重要。"},{"title":"房租与通勤的取舍","text":"在单中心城市模型里，住得越远房租越低、通勤越长，理性人会沿着这条线找平衡点。结果页给你的房租区间，就是按「房租不超过税后收入 30%」反推的。"},{"title":"落户与公共服务","text":"落户、买房资格、子女入学和医保，决定了一座城市能不能从「打工的地方」变成「生活的地方」。如果你在长期定居这一维得分高，这一项会比薪资更影响你的选择。"}],"boundary":["结果基于你自述的偏好，而不是对你能力的测评；同样的答案，换一种人生阶段可能有不同结论。","城市数据来自公开统计与生活经验的方向性整理，房租、通勤、薪资会随区域和时间波动，具体到片区仍需自行核实。","匹配度是七维剖面的接近程度，是刻度不是概率，也不代表你在这座城市一定能成功。","测试没有覆盖婚育、健康、签证、行业周期等个人约束，这些因素可能比得分更决定你的选择。","结果不构成求职、迁移、购房或投资建议。真正做决定前，建议先用一周时间实地住一住、投几份简历试试水。"]}'::jsonb,'2026-11-19 13:37:01+08') on conflict (id) do nothing;
insert into public.results (id,data,created_at) values ('g5kne86c39','{"pct":93,"cityName":"青岛","cityKey":"qingdao","conclusion":"你是青岛型：要气候和节奏，职业上接受稳而不快。","situation":"比起天花板，你更需要一份能覆盖生活、还能慢慢往上走的工作。","areas":["市南 · 香港中路","崂山 · 金家岭","黄岛 · 西海岸"],"vector":{"IND":58.3,"COST":66.7,"GATE":58.3,"PACE":41.7,"RISK":50.0,"FAM":50.0,"SETTLE":33.3},"dimRows":[{"key":"IND","name":"行业机会密度","score":58,"cityScore":58,"tendency":"需要岗位密集的大市场，随时能换赛道","reality":"家电制造、港口物流、海洋产业和旅游为主，互联网和高薪岗位少。","verdict":"行业面不宽，但和你的要求对得上，不用硬挤。","label":"合拍","aligned":true},{"key":"COST","name":"起步成本","score":67,"cityScore":60,"tendency":"对房租和生活开销敏感，先要活得起","reality":"市南一居 2500–3500，城阳 1500–2200；房租中等。","verdict":"房租和日常开销在你的预算内，起薪低一点也能存下钱。","label":"合拍","aligned":true},{"key":"GATE","name":"进入门槛","score":58,"cityScore":55,"tendency":"愿意在硬门槛里竞争，学历和履历拿得出手","reality":"制造业和国企看学历，外企分支少；考编竞争激烈。","verdict":"门槛不高，你的背景够用，进场比较容易。","label":"合拍","aligned":true},{"key":"PACE","name":"节奏与抗压","score":42,"cityScore":48,"tendency":"不愿用身体换钱，通勤和加班都要可控","reality":"通勤 35–45 分钟，节奏慢、加班少；跨海通勤耗时长。","verdict":"节奏慢，正合你意，时间能还给自己。","label":"合拍","aligned":true},{"key":"RISK","name":"风险与试错","score":50,"cityScore":45,"tendency":"敢试错，能接受空窗和转行","reality":"产业稳定但选择少，转行成本高。","verdict":"这里更看重稳定，你也不打算折腾，正好。","label":"合拍","aligned":true},{"key":"FAM","name":"家庭牵绊","score":50,"cityScore":50,"tendency":"需要离家近，家里的事要能搭把手","reality":"山东区域中心，省内高铁方便，北方家庭就近发展合适。","verdict":"离家远，但你对距离不敏感，问题不大。","label":"合拍","aligned":true},{"key":"SETTLE","name":"长期定居","score":33,"cityScore":55,"tendency":"不急着定居，先看机会","reality":"房价在计划单列市里偏低，落户宽松，气候宜居。","verdict":"这里比你现在需要的更适合安家，但你未必想被绑住。","label":"基本合拍","aligned":true}],"reasons":["先看机会和门槛。家电制造、港口物流、海洋产业和旅游为主，互联网和高薪岗位少。制造业和国企看学历，外企分支少；考编竞争激烈。对你来说，行业面不宽但够用，门槛不高，进场容易。","再看成本和节奏。市南一居 2500–3500，城阳 1500–2200；房租中等。通勤 35–45 分钟，节奏慢、加班少；跨海通勤耗时长。你的情况是：房租在你的预算内，节奏慢，正合你意。这里更看重稳定，你也不打算折腾，正好。","最后是家庭和定居。山东区域中心，省内高铁方便，北方家庭就近发展合适。房价在计划单列市里偏低，落户宽松，气候宜居。对你来说，离家远但你不敏感，这里比你现在需要的更适合安家。"],"industries":[{"name":"家电与智能制造","path":"校招","note":"崂山和西海岸，机械、电气对口。"},{"name":"港口物流与贸易","path":"社招","note":"货代、单证、供应链岗位稳定。"},{"name":"海洋与食品产业","path":"社招 / 考编","note":"本地特色，岗位数量有限。"}],"landing":["投递方向：机械或电气、供应链、外贸业务。","房租区间：城阳 1200–1800，市南合租 1800–2500。","落脚片区：2 号线李村，13 号线西海岸。"],"costs":["高薪岗位少。","冬天海风冷，体感温度低。","行业集中在制造和物流。"],"unfit":["想做互联网的人","需要高频跳槽涨薪的人","怕冷风的人"],"secondary":[{"city":"厦门","pct":91,"conclusion":"你是厦门型：愿意为气候和环境，接受更窄的职业选择。"},{"city":"天津","pct":90,"conclusion":"你是天津型：要北方大城市的资源，但不想付北京的代价。"},{"city":"昆明","pct":86,"conclusion":"你是昆明型：把生活质量和气候放在职业之前。"}],"reverse":{"city":"深圳","pct":58,"why":"它和你冲突最大的是「节奏与抗压」和「起步成本」：平均通勤 36 分钟，1 号线、4 号线早晚高峰是体力活；科技园凌晨打车要排队。南山一居 5500 起，城中村 1800–2800；房价收入比全国最高。","alternatives":[{"city":"广州","why":"一线机会，房租和节奏都低一档。"},{"city":"佛山","why":"制造业岗位多，广佛线可跨城通勤，成本再低三成。"}]},"theoryPanel":[{"title":"城市规模溢价","text":"大城市给同岗位开出更高工资，但同时把房租、通勤和竞争强度一起抬高。经济学上把这叫规模溢价：收入涨得快，成本涨得更快。所以「去大城市」本身不是答案，关键看你的起薪能不能跑赢房租。"},{"title":"厚劳动力市场","text":"岗位越密集，人和岗位的匹配效率越高，跳槽带来的涨薪也越明显。代价是你必须持续证明自己。对刚毕业和想转行的人，这层「匹配效率」往往比城市名气更重要。"},{"title":"房租与通勤的取舍","text":"在单中心城市模型里，住得越远房租越低、通勤越长，理性人会沿着这条线找平衡点。结果页给你的房租区间，就是按「房租不超过税后收入 30%」反推的。"},{"title":"落户与公共服务","text":"落户、买房资格、子女入学和医保，决定了一座城市能不能从「打工的地方」变成「生活的地方」。如果你在长期定居这一维得分高，这一项会比薪资更影响你的选择。"}],"boundary":["结果基于你自述的偏好，而不是对你能力的测评；同样的答案，换一种人生阶段可能有不同结论。","城市数据来自公开统计与生活经验的方向性整理，房租、通勤、薪资会随区域和时间波动，具体到片区仍需自行核实。","匹配度是七维剖面的接近程度，是刻度不是概率，也不代表你在这座城市一定能成功。","测试没有覆盖婚育、健康、签证、行业周期等个人约束，这些因素可能比得分更决定你的选择。","结果不构成求职、迁移、购房或投资建议。真正做决定前，建议先用一周时间实地住一住、投几份简历试试水。"]}'::jsonb,'2026-11-19 13:32:39+08') on conflict (id) do nothing;
insert into public.results (id,data,created_at) values ('gm62b8b5py','{"pct":80,"typeId":1,"key":"poet","name":"凌晨便利店诗人","tagline":"城市越大，我越晚睡，也越自由。","chips":["夜行型","高刺激","便利店依赖","城市动物","一个人但不孤独"],"cities":[{"city":"上海","areas":"静安、黄浦、长宁（中山公园—愚园路）"},{"city":"深圳","areas":"南山、福田（车公庙、购物公园）"},{"city":"广州","areas":"天河、越秀（体育西、东山口）"},{"city":"杭州","areas":"拱墅、西湖区（武林、黄龙）"}],"profile":["你的一天从晚上十点开始。白天是义务，夜里才是自己的。","你能在 24 小时便利店里找到一种奇怪的归属感：关东煮的热气、收银员那句「需要袋子吗」、玻璃窗外的车流。","你怕的不是孤独，是无聊。你需要城市一直亮着，来证明你也没睡。","你的微信置顶有三个人，但你深夜真正会拨出去的，是外卖软件。"],"why":"你需要的不只是「夜生活」，而是夜间供给的密度：便利店、宵夜、深夜书店、凌晨还能打到车。这种密度只在一线城市的核心城区成立，因为它是人口密度、商业租金、夜班人力三者共同撑起来的。同时你对异质性的容忍度高——街上的人越杂，你越自在。","costs":["房租会吃掉你夜里消费的自由——你以为你在享受城市，其实在给房东打工。","睡眠债是复利的。二十六岁能扛，三十二岁开始还。","关系会变浅。深夜的便利店很温暖，但它不会记得你。"],"unfit":["冬天八点街上就空了的北方小城","需要早起、且家里有老人小孩的作息","你对「人多」的耐受其实没有自己以为的那么高"],"theoryTitle":"齐美尔的都市精神生活","theory":"齐美尔在《大都市与精神生活》里说，都市用高频刺激和货币经济塑造出一种「矜持而厌倦」的人格：你必须对太多刺激保持麻木，才能活下去。你熟悉的那种「在人群里最自在、却也最容易累」，不是性格缺陷，而是都市性的典型代价。沃斯进一步指出，规模、密度与异质性会带来匿名与次级关系——这既是你的自由，也是你深夜想找人说句话时，手机翻不出人的原因。","share":"我不是睡不着，我是在等这座城市先睡。","matchReason":"你的答卷里有两个信号特别明显：你在「文化密度」上得分很高（需要持续的文化刺激），在「夜间节律」上得分很高（越晚越清醒，夜里需要城市还开着）。上海恰好在这两件事上同时给出了回应——每周都有演出和展览，凌晨两点还有便利店和夜班车。城市用密度喂养你，也用密度消耗你——这是同一件事。。所以它未必是「最好的城市」，但它和你咬合得最紧。","cityName":"上海","night":{"label":"夜行动物","modifier":"服务依赖型","prescription":"你的安全感来自「随时能点到」。外卖覆盖率和便利店密度，比房租更值得你研究。"},"vector":{"N":97.2,"P":54.2,"O":100.0,"C":25.0,"K":100.0,"S":66.7,"M":66.7},"secondary":[{"name":"新一线性价比信徒","pct":75},{"name":"末班地铁赶路人","pct":72}],"reverse":{"name":"森林边早睡者","pct":55,"city":"丽水"},"migratory":false,"migratoryType":null,"theoryPanel":[{"title":"人-环境匹配（P-E Fit）","body":"行为是人与环境交互的函数。本测试只测「需求-供给」匹配：七个维度是七种需求，城市原型是七种供给组合。匹配度描述的是「像不像」，不是「会不会幸福」。"},{"title":"恢复性环境理论（ART）","body":"自然环境的「离开感、柔和魅力、范围感、兼容性」能恢复被城市消耗的定向注意力。它解释了为什么有人住得越偏反而越好。"},{"title":"通勤悖论","body":"人们系统性低估长通勤对幸福的侵蚀，且事后补偿往往不足。中国主要城市通勤监测报告也显示，极端通勤比重在城市间差异显著。"},{"title":"都市社会学","body":"齐美尔讲都市刺激与倦怠，沃斯讲规模、密度与异质性带来的匿名，费孝通讲熟人社会与差序格局，项飙讲「附近的消失」。"},{"title":"气候与情绪","body":"季节性情感障碍（SAD）与光照时长相关；湿热、干燥与室内热舒适也真实影响睡眠与情绪。气候不是矫情，是身体。"},{"title":"生活方式迁移","body":"为生活方式而非工作迁移，是真实且增长中的现象。它带来自由，也带来身份感与成本的长期拉扯。"}],"boundary":["自报偏好不等于真实适应：结果反映你「此刻的想象」，不反映长期适应。","适应力被低估：搬家 6–12 个月后情绪常回弹，无论去哪。","百分比不是概率：它是剖面相似度刻度，不是「87% 的人会幸福」。","生态谬误：同城不同区的差异，可能大于城市之间。","硬约束未纳入：户籍、家庭、行业、健康、婚育、房贷，往往比城市气质更能决定结果。","样本与工具偏差：自编题目，未做心理测量学标准化检验。"]}'::jsonb,'2026-11-19 13:03:36+08') on conflict (id) do nothing;
insert into public.results (id,data,created_at) values ('mv3q6agpyf','{"pct":80,"cityName":"深圳","cityKey":"shenzhen","conclusion":"你是深圳型：要速度和增量，愿意用几年高强度换一个位置。","situation":"你现在缺的不是热情，是一份能积累的履历。","areas":["南山 · 科技园 / 后海","福田 · 车公庙","宝安 · 西乡"],"vector":{"IND":100.0,"COST":0.0,"GATE":100.0,"PACE":100.0,"RISK":100.0,"FAM":0.0,"SETTLE":0.0},"dimRows":[{"key":"IND","name":"行业机会密度","score":100,"cityScore":95,"tendency":"需要岗位密集的大市场，随时能换赛道","reality":"硬件、互联网、跨境电商、新能源总部密集，跳槽涨薪路径全国最短。","verdict":"岗位密度和你的预期对得上，换方向不用换城。","label":"合拍","aligned":true},{"key":"COST","name":"起步成本","score":0,"cityScore":26,"tendency":"能接受高房租，把它当机会成本","reality":"南山一居 5500 起，城中村 1800–2800；房价收入比全国最高。","verdict":"成本高，但你本来就不打算在住上省钱。","label":"基本合拍","aligned":true},{"key":"GATE","name":"进入门槛","score":100,"cityScore":90,"tendency":"愿意在硬门槛里竞争，学历和履历拿得出手","reality":"校招看学校和大厂实习，社招看项目；学历门槛略松，但加班强度是隐性门槛。","verdict":"门槛和你的准备匹配，进正门不用绕道。","label":"合拍","aligned":true},{"key":"PACE","name":"节奏与抗压","score":100,"cityScore":96,"tendency":"能扛快节奏和加班，把前几年当投入","reality":"平均通勤 36 分钟，1 号线、4 号线早晚高峰是体力活；科技园凌晨打车要排队。","verdict":"节奏快，但你能扛，前几年能换来位置。","label":"合拍","aligned":true},{"key":"RISK","name":"风险与试错","score":100,"cityScore":82,"tendency":"敢试错，能接受空窗和转行","reality":"创业和试错氛围最浓，失败一次还能再来；但 35 岁后的淘汰也最直接。","verdict":"试错空间和你的胆量匹配，失败一次还有退路。","label":"合拍","aligned":true},{"key":"FAM","name":"家庭牵绊","score":0,"cityScore":20,"tendency":"家庭牵绊小，可以去远一点的地方","reality":"移民城市，外省人一年回两三次家；广东本地人周末可回。","verdict":"离家远，但你对距离不敏感，问题不大。","label":"合拍","aligned":true},{"key":"SETTLE","name":"长期定居","score":0,"cityScore":35,"tendency":"不急着定居，先看机会","reality":"学历落户相对容易，但买房难，多数人先落户再观望。","verdict":"定居条件一般，不过你也不急着定居。","label":"基本合拍","aligned":true}],"reasons":["先看机会和门槛。硬件、互联网、跨境电商、新能源总部密集，跳槽涨薪路径全国最短。校招看学校和大厂实习，社招看项目；学历门槛略松，但加班强度是隐性门槛。对你来说，岗位密度和你的预期对得上，门槛和你的准备匹配。","再看成本和节奏。南山一居 5500 起，城中村 1800–2800；房价收入比全国最高。平均通勤 36 分钟，1 号线、4 号线早晚高峰是体力活；科技园凌晨打车要排队。你的情况是：成本高但你不在意，节奏快但你能扛。试错空间和你的胆量匹配，失败一次还有退路。","最后是家庭和定居。移民城市，外省人一年回两三次家；广东本地人周末可回。学历落户相对容易，但买房难，多数人先落户再观望。对你来说，离家远但你不敏感，定居条件一般，你也不急。"],"industries":[{"name":"硬件与智能终端","path":"校招 / 社招","note":"南山和宝安集中，结构、嵌入式、供应链岗位多。"},{"name":"跨境电商","path":"社招","note":"门槛低、看执行，英语和小语种加分。"},{"name":"互联网平台","path":"校招","note":"卡实习和大厂经历，节奏最快。"}],"landing":["投递方向：硬件、结构、嵌入式、跨境运营，先投 50–500 人公司，拿到 offer 再跳大厂。","房租区间：城中村 1800–2800，小区合租 2500–3500。","落脚片区：1 号线宝安段、5 号线坂田段，通勤 40 分钟内。"],"costs":["房价收入比全国最高，留下来的成本每年都在涨。","文化供给仍偏薄，深夜除了吃和加班，选择不多。","所有人都在赶路，关系来得快、散得也快。"],"unfit":["想慢下来生活的人","需要深厚文化氛围和稳定熟人圈的人","把买房安家当五年目标的人"],"secondary":[{"city":"上海","pct":78,"conclusion":"你是上海型：要专业分工和秩序，也接受用收入换位置。"},{"city":"北京","pct":78,"conclusion":"你是北京型：要行业天花板，愿意为它多付房租和通勤。"},{"city":"杭州","pct":64,"conclusion":"你是杭州型：能卷，但不肯卷到失去生活。"}],"reverse":{"city":"沈阳","pct":50,"why":"它和你冲突最大的是「起步成本」和「家庭牵绊」：一居 1200–1800，合租 800–1200；生活成本全国最低一档。东北区域中心，省内高铁方便，父母期待就近发展的压力大。","alternatives":[{"city":"天津","why":"岗位层次更高，高铁 2 小时。"},{"city":"青岛","why":"气候更温和，制造业相近。"}]},"theoryPanel":[{"title":"城市规模溢价","text":"大城市给同岗位开出更高工资，但同时把房租、通勤和竞争强度一起抬高。经济学上把这叫规模溢价：收入涨得快，成本涨得更快。所以「去大城市」本身不是答案，关键看你的起薪能不能跑赢房租。"},{"title":"厚劳动力市场","text":"岗位越密集，人和岗位的匹配效率越高，跳槽带来的涨薪也越明显。代价是你必须持续证明自己。对刚毕业和想转行的人，这层「匹配效率」往往比城市名气更重要。"},{"title":"房租与通勤的取舍","text":"在单中心城市模型里，住得越远房租越低、通勤越长，理性人会沿着这条线找平衡点。结果页给你的房租区间，就是按「房租不超过税后收入 30%」反推的。"},{"title":"落户与公共服务","text":"落户、买房资格、子女入学和医保，决定了一座城市能不能从「打工的地方」变成「生活的地方」。如果你在长期定居这一维得分高，这一项会比薪资更影响你的选择。"}],"boundary":["结果基于你自述的偏好，而不是对你能力的测评；同样的答案，换一种人生阶段可能有不同结论。","城市数据来自公开统计与生活经验的方向性整理，房租、通勤、薪资会随区域和时间波动，具体到片区仍需自行核实。","匹配度是七维剖面的接近程度，是刻度不是概率，也不代表你在这座城市一定能成功。","测试没有覆盖婚育、健康、签证、行业周期等个人约束，这些因素可能比得分更决定你的选择。","结果不构成求职、迁移、购房或投资建议。真正做决定前，建议先用一周时间实地住一住、投几份简历试试水。"]}'::jsonb,'2026-11-19 13:37:01+08') on conflict (id) do nothing;
insert into public.results (id,data,created_at) values ('tfqt8fankd','{"pct":93,"cityName":"大理","cityKey":"dali","conclusion":"大理：全国最慢的一档，适合远程，不适合找本地工作。","situation":"你现在要的不是一份城市榜单，而是一个能慢下来、也不用太拼命的地方。","portrait":{"text":"你要的是慢一点、出门见山见水、住得起；能接受文化资源少一点、新东西少一点。这不是旅行偏好，是你打算长期住下去时，最先受不了和最先离不开的部分。","vector":{"PACE":100,"FOOD":67,"CULT":33,"TECH":33,"NAT":100,"NIGHT":33,"SHOP":33,"CLIM":67,"COST":100,"GREEN":100},"top":[{"name":"生活节奏","score":100},{"name":"自然环境","score":100},{"name":"居住成本","score":100}],"low":[{"name":"文化历史","score":33},{"name":"科技创新","score":33}]},"vector":{"PACE":100,"FOOD":67,"CULT":33,"TECH":33,"NAT":100,"NIGHT":33,"SHOP":33,"CLIM":67,"COST":100,"GREEN":100},"dimRows":[{"key":"PACE","name":"生活节奏","score":100,"cityScore":95,"gap":5,"label":"合拍","aligned":true,"tendency":"你想慢下来，时间要能还给自己","reality":"全国最慢的一档，午后街上多是闲坐的人","verdict":"节奏对得上，你不用刻意调快或调慢。"},{"key":"FOOD","name":"美食多元","score":67,"cityScore":62,"gap":5,"label":"合拍","aligned":true,"tendency":"你把吃当成日常的重要部分，选择要多","reality":"白族菜与云南菜，选择有限但食材好","verdict":"吃的选择够你换着来，日常不会腻。"},{"key":"CULT","name":"文化历史","score":33,"cityScore":45,"gap":12,"label":"合拍","aligned":true,"tendency":"你对历史文博没什么兴趣","reality":"大理古城、崇圣寺三塔、喜洲古镇","verdict":"你对这些不执着，城市年轻也不影响你。"},{"key":"TECH","name":"科技创新","score":33,"cityScore":28,"gap":5,"label":"合拍","aligned":true,"tendency":"你对科技无感，传统方式更踏实","reality":"岗位极少，远程工作者聚集","verdict":"你不需要新东西，这里慢一点也无所谓。"},{"key":"NAT","name":"自然环境","score":100,"cityScore":97,"gap":3,"label":"合拍","aligned":true,"tendency":"你需要山、水、蓝天，出门就能碰到自然","reality":"苍山洱海，出门即景","verdict":"山或水在通勤范围内，出门就能换气。"},{"key":"NIGHT","name":"夜生活","score":33,"cityScore":45,"gap":12,"label":"合拍","aligned":true,"tendency":"你晚上不出门，安静更重要","reality":"人民路小酒馆，凌晨仍有人","verdict":"你睡得早，这里收摊早正好。"},{"key":"SHOP","name":"购物消费","score":33,"cityScore":38,"gap":5,"label":"合拍","aligned":true,"tendency":"你很少逛街，够用就行","reality":"商业以古城小店为主，品牌少","verdict":"你买得少，这里的商业够日常。"},{"key":"CLIM","name":"气候偏好","score":67,"cityScore":60,"gap":7,"label":"合拍","aligned":true,"tendency":"你怕冷，喜欢温暖湿润","reality":"高原季风，日照强，冬季干冷，紫外线高","verdict":"气候体感合你，冬天不用硬扛。"},{"key":"COST","name":"居住成本","score":100,"cityScore":66,"gap":34,"label":"需要适应","aligned":false,"tendency":"你要低开销，房租不能吃掉生活","reality":"古城外一居 1500-2000，开销低","verdict":"这里比你预期的贵，房租会吃掉一部分生活。"},{"key":"GREEN","name":"城市绿化","score":100,"cityScore":82,"gap":18,"label":"基本合拍","aligned":true,"tendency":"你要树荫、公园和能走的路","reality":"苍山植被与洱海湿地，覆盖率约 45%","verdict":"绿地和公园比你要的少，散步要挑地方。"}],"reasons":[{"title":"节奏与成本","text":"先说每天的时间感和开销。生活节奏：全国最慢的一档，午后街上多是闲坐的人。节奏对得上，你不用刻意调快或调慢。居住成本：古城外一居 1500-2000，开销低。这里比你预期的贵，房租会吃掉一部分生活。","dims":["PACE","COST"]},{"title":"吃、逛与夜晚","text":"再看日常的消费与夜晚。美食多元：白族菜与云南菜，选择有限但食材好。吃的选择够你换着来，日常不会腻。购物消费：商业以古城小店为主，品牌少。你买得少，这里的商业够日常。夜生活：人民路小酒馆，凌晨仍有人。你睡得早，这里收摊早正好。","dims":["FOOD","SHOP","NIGHT"]},{"title":"文化、自然与绿地","text":"然后是能走能看的部分。文化历史：大理古城、崇圣寺三塔、喜洲古镇。你对这些不执着，城市年轻也不影响你。自然环境：苍山洱海，出门即景。山或水在通勤范围内，出门就能换气。城市绿化：苍山植被与洱海湿地，覆盖率约 45%。绿地和公园比你要的少，散步要挑地方。","dims":["CULT","NAT","GREEN"]},{"title":"科技与气候","text":"最后是效率与体感。科技创新：岗位极少，远程工作者聚集。你不需要新东西，这里慢一点也无所谓。气候偏好：高原季风，日照强，冬季干冷，紫外线高。气候体感合你，冬天不用硬扛。","dims":["TECH","CLIM"]}],"tradeoffs":["没有像样的本地就业市场","医疗与教育配套弱"],"secondary":[{"city":"桂林","pct":93,"conclusion":"桂林：山水是最好的日常，城市配套偏基础。","reason":"和大理相比，更暖湿、吃的选择更多，但更快、更赶。"},{"city":"丽江","pct":89,"conclusion":"丽江：慢到极致，但日常便利和岗位都很少。","reason":"和大理相比，历史文博更密、夜生活更旺，但更干冷。"},{"city":"昆明","pct":87,"conclusion":"昆明：气候这张牌全国少有对手，代价是节奏和机会都慢。","reason":"和大理相比，科技感更强、商业更发达，但更快、更赶。"}],"reverse":{"city":"上海","pct":45,"why":"居住成本：内环一居 6000 起，房租收入比长期偏高（这里比你想要的弱）自然环境：临江临海但地势平，最近的山水在 1.5 小时车程外（这里比你想要的弱）","alternatives":[{"city":"海口","pct":87,"why":"和上海相比，更慢、自然更近，但科技氛围淡一些。"},{"city":"贵阳","pct":86,"why":"和上海相比，生活成本更低、自然更近，但逛街选择少。"}]},"theoryPanel":[{"title":"城市规模决定选择的数量","text":"城市越大，餐饮、展览、演出、夜宵的种类越多；但同样的丰富度，也意味着更长的通勤和更高的房租。丰富和松弛很少同时免费。"},{"title":"气候是最难改的变量","text":"气候无法靠个人努力调整。冬季日照、夏季湿度、雨季长度，会长期影响睡眠、情绪和出门频率，是选城时最值得当硬指标的一项。"},{"title":"绿地与通勤决定日常松弛","text":"绿地率、公园密度、平均通勤时间，决定散步和发呆是日常还是周末特权。它们不显眼，却最直接影响每天的状态。"},{"title":"居住成本决定选择权","text":"成本低的城市，意味着你可以接受薪水更低但更喜欢的工作、更长的空窗期。成本高则要求收入持续向上，选择会被压缩。"}],"boundary":["题目为自编，未做心理测量学标准化检验；维度分是偏好刻度，不是能力或人格测评。","城市十维坐标基于公开统计与生活经验的方向性整理（气候、绿地率、夜经济、餐饮多样性、历史街区与博物馆密度、消费水平等），会随年份和片区变化。","十个维度独立计分，不做相互抵消：某一维的高分不能补另一维的明显错位，错位维度会单独列出并计入扣分。","匹配度是剖面接近程度，不是概率，也不代表搬过去一定过得好。","结果不构成迁移、购房、医疗或投资建议；具体片区的房租、通勤、气候体感仍需自行核实。"],"matchNote":"十维等权独立计分，任一维差距 ≥45 会单独扣分并压低匹配度上限，不用其他维度的高分抵消。"}'::jsonb,'2026-11-19 14:01:32+08') on conflict (id) do nothing;
insert into public.results (id,data,created_at) values ('vz77bv82uv','{"pct":61,"cityName":"沈阳","cityKey":"shenyang","conclusion":"你是沈阳型：要低成本、低门槛，先把日子稳住。","situation":"你要解决的不是「去哪闯」，而是「离家不远、又能站住」这道题。","areas":["和平 · 太原街","浑南 · 奥体","铁西 · 启工"],"vector":{"IND":33.3,"COST":100.0,"GATE":0.0,"PACE":0.0,"RISK":0.0,"FAM":100.0,"SETTLE":100.0},"dimRows":[{"key":"IND","name":"行业机会密度","score":33,"cityScore":50,"tendency":"不依赖行业数量，一份对口的工作就够","reality":"装备制造、汽车、军工和医疗为主，新兴行业岗位少。","verdict":"行业面不宽，但和你的要求对得上，不用硬挤。","label":"合拍","aligned":true},{"key":"COST","name":"起步成本","score":100,"cityScore":82,"tendency":"对房租和生活开销敏感，先要活得起","reality":"一居 1200–1800，合租 800–1200；生活成本全国最低一档。","verdict":"房租和日常开销在你的预算内，起薪低一点也能存下钱。","label":"合拍","aligned":true},{"key":"GATE","name":"进入门槛","score":0,"cityScore":45,"tendency":"更想绕开硬门槛，找一条能先进场的路","reality":"制造业和国企看学历与技能证书，整体门槛低；考编竞争激烈。","verdict":"门槛很低，进去容易，但天花板也低。","label":"需要适应","aligned":false},{"key":"PACE","name":"节奏与抗压","score":0,"cityScore":45,"tendency":"不愿用身体换钱，通勤和加班都要可控","reality":"通勤 30–40 分钟，节奏慢，加班少。","verdict":"节奏很慢，可能会觉得闲，但身体轻松。","label":"需要适应","aligned":false},{"key":"RISK","name":"风险与试错","score":0,"cityScore":38,"tendency":"需要确定性，先站稳再谈发展","reality":"生活成本极低，试错压力小；但岗位少，失败后选择有限。","verdict":"这里要的是确定性，你也不想冒险，匹配。","label":"需要适应","aligned":false},{"key":"FAM","name":"家庭牵绊","score":100,"cityScore":72,"tendency":"需要离家近，家里的事要能搭把手","reality":"东北区域中心，省内高铁方便，父母期待就近发展的压力大。","verdict":"离家比你希望的要远，回一趟成本高。","label":"基本合拍","aligned":true},{"key":"SETTLE","name":"长期定居","score":100,"cityScore":70,"tendency":"在意落户、买房和长期安家","reality":"房价极低、落户容易，医疗教育资源集中，定居压力最小。","verdict":"定居门槛比你想要的更紧，更适合当积累履历的一站。","label":"基本合拍","aligned":true}],"reasons":["先看机会和门槛。装备制造、汽车、军工和医疗为主，新兴行业岗位少。制造业和国企看学历与技能证书，整体门槛低；考编竞争激烈。对你来说，行业面不宽但够用，门槛低，但天花板也低。","再看成本和节奏。一居 1200–1800，合租 800–1200；生活成本全国最低一档。通勤 30–40 分钟，节奏慢，加班少。你的情况是：房租在你的预算内，节奏很慢，可能觉得闲。这里要的是确定性，你也不想冒险，匹配。","最后是家庭和定居。东北区域中心，省内高铁方便，父母期待就近发展的压力大。房价极低、落户容易，医疗教育资源集中，定居压力最小。对你来说，离家比你希望的要远，定居门槛比你想要的更紧。"],"industries":[{"name":"装备制造与汽车","path":"校招","note":"铁西和大东，机械、焊接、电气岗位多。"},{"name":"军工与航空","path":"校招 / 考编","note":"稳定，政审严格。"},{"name":"医疗与养老服务","path":"社招","note":"人口老龄化带来稳定需求。"}],"landing":["投递方向：机械、电气、焊接工艺、设备维护、医药销售。","房租区间：800–1500；月薪六千可存三千。","落脚片区：2 号线奥体，1 号线铁西。"],"costs":["薪资低，涨薪慢。","民营经济弱，行业选择少。","冬天漫长寒冷。"],"unfit":["想拿高薪的人","需要行业多样性的人","怕冷的人"],"secondary":[{"city":"大理","pct":60,"conclusion":"你是大理型：要自己掌控节奏，但需要一份能远程的收入。"},{"city":"昆明","pct":57,"conclusion":"你是昆明型：把生活质量和气候放在职业之前。"},{"city":"重庆","pct":50,"conclusion":"你是重庆型：要低成本的落脚点，也接受行业选择没那么宽。"}],"reverse":{"city":"深圳","pct":50,"why":"它和你冲突最大的是「节奏与抗压」和「进入门槛」：平均通勤 36 分钟，1 号线、4 号线早晚高峰是体力活；科技园凌晨打车要排队。校招看学校和大厂实习，社招看项目；学历门槛略松，但加班强度是隐性门槛。","alternatives":[{"city":"广州","why":"一线机会，房租和节奏都低一档。"},{"city":"佛山","why":"制造业岗位多，广佛线可跨城通勤，成本再低三成。"}]},"theoryPanel":[{"title":"城市规模溢价","text":"大城市给同岗位开出更高工资，但同时把房租、通勤和竞争强度一起抬高。经济学上把这叫规模溢价：收入涨得快，成本涨得更快。所以「去大城市」本身不是答案，关键看你的起薪能不能跑赢房租。"},{"title":"厚劳动力市场","text":"岗位越密集，人和岗位的匹配效率越高，跳槽带来的涨薪也越明显。代价是你必须持续证明自己。对刚毕业和想转行的人，这层「匹配效率」往往比城市名气更重要。"},{"title":"房租与通勤的取舍","text":"在单中心城市模型里，住得越远房租越低、通勤越长，理性人会沿着这条线找平衡点。结果页给你的房租区间，就是按「房租不超过税后收入 30%」反推的。"},{"title":"落户与公共服务","text":"落户、买房资格、子女入学和医保，决定了一座城市能不能从「打工的地方」变成「生活的地方」。如果你在长期定居这一维得分高，这一项会比薪资更影响你的选择。"}],"boundary":["结果基于你自述的偏好，而不是对你能力的测评；同样的答案，换一种人生阶段可能有不同结论。","城市数据来自公开统计与生活经验的方向性整理，房租、通勤、薪资会随区域和时间波动，具体到片区仍需自行核实。","匹配度是七维剖面的接近程度，是刻度不是概率，也不代表你在这座城市一定能成功。","测试没有覆盖婚育、健康、签证、行业周期等个人约束，这些因素可能比得分更决定你的选择。","结果不构成求职、迁移、购房或投资建议。真正做决定前，建议先用一周时间实地住一住、投几份简历试试水。"]}'::jsonb,'2026-11-19 13:25:28+08') on conflict (id) do nothing;
insert into public.results (id,data,created_at) values ('w3hcbyhbpu','{"pct":93,"cityName":"南昌","cityKey":"nanchang","conclusion":"南昌：成本极低，赣江边的生活简单直接。","situation":"你要的是一个能长期待下去、日常不太费劲的地方。","portrait":{"text":"你要的是慢一点、出门见山见水、冬天别太冷；能接受文化资源少一点、新东西少一点。这不是旅行偏好，是你打算长期住下去时，最先受不了和最先离不开的部分。","vector":{"PACE":67,"FOOD":53,"CULT":40,"TECH":40,"NAT":60,"NIGHT":53,"SHOP":47,"CLIM":60,"COST":60,"GREEN":53},"top":[{"name":"生活节奏","score":67},{"name":"自然环境","score":60},{"name":"气候偏好","score":60}],"low":[{"name":"文化历史","score":40},{"name":"科技创新","score":40}]},"vector":{"PACE":67,"FOOD":53,"CULT":40,"TECH":40,"NAT":60,"NIGHT":53,"SHOP":47,"CLIM":60,"COST":60,"GREEN":53},"dimRows":[{"key":"PACE","name":"生活节奏","score":67,"cityScore":72,"gap":5,"label":"合拍","aligned":true,"tendency":"你想慢下来，时间要能还给自己","reality":"节奏偏慢，物价低","verdict":"节奏对得上，你不用刻意调快或调慢。"},{"key":"FOOD","name":"美食多元","score":53,"cityScore":72,"gap":19,"label":"基本合拍","aligned":true,"tendency":"你把吃当成日常的重要部分，选择要多","reality":"赣菜偏辣，拌粉瓦罐汤是日常","verdict":"这里的餐饮密度超过你的日常需求，算是余量。"},{"key":"CULT","name":"文化历史","score":40,"cityScore":55,"gap":15,"label":"合拍","aligned":true,"tendency":"你对历史文博没什么兴趣","reality":"滕王阁、八一起义纪念馆、海昏侯墓","verdict":"你对这些不执着，城市年轻也不影响你。"},{"key":"TECH","name":"科技创新","score":40,"cityScore":50,"gap":10,"label":"合拍","aligned":true,"tendency":"你对科技无感，传统方式更踏实","reality":"电子信息与 VR 产业，规模中等","verdict":"你不需要新东西，这里慢一点也无所谓。"},{"key":"NAT","name":"自然环境","score":60,"cityScore":62,"gap":2,"label":"合拍","aligned":true,"tendency":"你需要山、水、蓝天，出门就能碰到自然","reality":"赣江穿城，梅岭在城西","verdict":"山或水在通勤范围内，出门就能换气。"},{"key":"NIGHT","name":"夜生活","score":53,"cityScore":58,"gap":5,"label":"合拍","aligned":true,"tendency":"你的晚上才开始，需要城市还醒着","reality":"夜宵以烧烤为主，秋水广场","verdict":"你睡得早，这里收摊早正好。"},{"key":"SHOP","name":"购物消费","score":47,"cityScore":55,"gap":8,"label":"合拍","aligned":true,"tendency":"你很少逛街，够用就行","reality":"中山路、万达","verdict":"你买得少，这里的商业够日常。"},{"key":"CLIM","name":"气候偏好","score":60,"cityScore":80,"gap":20,"label":"基本合拍","aligned":true,"tendency":"你怕冷，喜欢温暖湿润","reality":"夏季酷热，冬季湿冷，春秋短","verdict":"这里比你需要的更暖湿，夏天要适应。"},{"key":"COST","name":"居住成本","score":60,"cityScore":74,"gap":14,"label":"合拍","aligned":true,"tendency":"你要低开销，房租不能吃掉生活","reality":"市区一居 1500 左右，开销很低","verdict":"房租和日常开销都在你能接受的范围内。"},{"key":"GREEN","name":"城市绿化","score":53,"cityScore":64,"gap":11,"label":"合拍","aligned":true,"tendency":"你要树荫、公园和能走的路","reality":"绿化覆盖率约 42%，赣江风光带","verdict":"树荫、公园和绿道是日常，不是周末项目。"}],"reasons":[{"title":"节奏与成本","text":"先说每天的时间感和开销。生活节奏：节奏偏慢，物价低。节奏对得上，你不用刻意调快或调慢。居住成本：市区一居 1500 左右，开销很低。房租和日常开销都在你能接受的范围内。","dims":["PACE","COST"]},{"title":"吃、逛与夜晚","text":"再看日常的消费与夜晚。美食多元：赣菜偏辣，拌粉瓦罐汤是日常。这里的餐饮密度超过你的日常需求，算是余量。购物消费：中山路、万达。你买得少，这里的商业够日常。夜生活：夜宵以烧烤为主，秋水广场。你睡得早，这里收摊早正好。","dims":["FOOD","SHOP","NIGHT"]},{"title":"文化、自然与绿地","text":"然后是能走能看的部分。文化历史：滕王阁、八一起义纪念馆、海昏侯墓。你对这些不执着，城市年轻也不影响你。自然环境：赣江穿城，梅岭在城西。山或水在通勤范围内，出门就能换气。城市绿化：绿化覆盖率约 42%，赣江风光带。树荫、公园和绿道是日常，不是周末项目。","dims":["CULT","NAT","GREEN"]},{"title":"科技与气候","text":"最后是效率与体感。科技创新：电子信息与 VR 产业，规模中等。你不需要新东西，这里慢一点也无所谓。气候偏好：夏季酷热，冬季湿冷，春秋短。这里比你需要的更暖湿，夏天要适应。","dims":["TECH","CLIM"]}],"tradeoffs":["夏季酷热","文化娱乐供给有限"],"secondary":[{"city":"济南","pct":92,"conclusion":"济南：泉水和大明湖撑起了日常，节奏不快。","reason":"和南昌相比，历史文博更密，但更干冷。"},{"city":"东莞","pct":91,"conclusion":"东莞：成本低、离广深近，城市生活感偏弱。","reason":"和南昌相比，科技感更强、商业更发达，但文化设施少一些。"},{"city":"兰州","pct":90,"conclusion":"兰州：一条黄河穿城，牛肉面和低成本撑起日常。","reason":"和南昌相比，更慢，但更干冷。"}],"reverse":{"city":"北京","pct":53,"why":"文化历史：7 处世界遗产，备案博物馆 170 余家，故宫与国博常年预约满（这里比你要的多）科技创新：中关村、望京、亦庄三点分布，互联网与 AI 公司全国最集中（这里比你要的多）","alternatives":[{"city":"贵阳","pct":89,"why":"和北京相比，生活成本更低、自然更近，但文化设施少一些。"},{"city":"西宁","pct":88,"why":"和北京相比，更慢、生活成本更低，但科技氛围淡一些。"}]},"theoryPanel":[{"title":"城市规模决定选择的数量","text":"城市越大，餐饮、展览、演出、夜宵的种类越多；但同样的丰富度，也意味着更长的通勤和更高的房租。丰富和松弛很少同时免费。"},{"title":"气候是最难改的变量","text":"气候无法靠个人努力调整。冬季日照、夏季湿度、雨季长度，会长期影响睡眠、情绪和出门频率，是选城时最值得当硬指标的一项。"},{"title":"绿地与通勤决定日常松弛","text":"绿地率、公园密度、平均通勤时间，决定散步和发呆是日常还是周末特权。它们不显眼，却最直接影响每天的状态。"},{"title":"居住成本决定选择权","text":"成本低的城市，意味着你可以接受薪水更低但更喜欢的工作、更长的空窗期。成本高则要求收入持续向上，选择会被压缩。"}],"boundary":["题目为自编，未做心理测量学标准化检验；维度分是偏好刻度，不是能力或人格测评。","城市十维坐标基于公开统计与生活经验的方向性整理（气候、绿地率、夜经济、餐饮多样性、历史街区与博物馆密度、消费水平等），会随年份和片区变化。","十个维度独立计分，不做相互抵消：某一维的高分不能补另一维的明显错位，错位维度会单独列出并计入扣分。","匹配度是剖面接近程度，不是概率，也不代表搬过去一定过得好。","结果不构成迁移、购房、医疗或投资建议；具体片区的房租、通勤、气候体感仍需自行核实。"],"matchNote":"十维等权独立计分，任一维差距 ≥45 会单独扣分并压低匹配度上限，不用其他维度的高分抵消。"}'::jsonb,'2026-11-19 14:12:53+08') on conflict (id) do nothing;
insert into public.results (id,data,created_at) values ('wqfg2u5y3g','{"pct":88,"cityName":"深圳","cityKey":"shenzhen","conclusion":"深圳：山海和效率都在线，历史薄、房价高。","situation":"你要的不是景点，是下班以后还有地方可去。","portrait":{"text":"你要的是吃得好、新东西跟得上、夜里有的玩；能接受节奏快一点、山水远一点。这不是旅行偏好，是你打算长期住下去时，最先受不了和最先离不开的部分。","vector":{"PACE":0,"FOOD":100,"CULT":67,"TECH":100,"NAT":33,"NIGHT":100,"SHOP":100,"CLIM":100,"COST":33,"GREEN":67},"top":[{"name":"美食多元","score":100},{"name":"科技创新","score":100},{"name":"夜生活","score":100}],"low":[{"name":"生活节奏","score":0},{"name":"自然环境","score":33}]},"vector":{"PACE":0,"FOOD":100,"CULT":67,"TECH":100,"NAT":33,"NIGHT":100,"SHOP":100,"CLIM":100,"COST":33,"GREEN":67},"dimRows":[{"key":"PACE","name":"生活节奏","score":0,"cityScore":35,"gap":35,"label":"需要适应","aligned":false,"tendency":"你习惯快节奏，闲下来反而不安","reality":"平均通勤约 36 分钟，但加班普遍，写字楼夜间灯火密度高","verdict":"这里节奏偏快，你也不算抗拒，勉强能对上。"},{"key":"FOOD","name":"美食多元","score":100,"cityScore":82,"gap":18,"label":"基本合拍","aligned":true,"tendency":"你把吃当成日常的重要部分，选择要多","reality":"移民城市，潮汕菜、湘菜、川菜与东南亚菜并存，本地菜薄","verdict":"你想吃的这里给不全，得降低预期或自己找。"},{"key":"CULT","name":"文化历史","score":67,"cityScore":45,"gap":22,"label":"基本合拍","aligned":true,"tendency":"你需要有旧东西可看，博物馆和老街是日常","reality":"历史短，南头古城、大鹏所城规模小，博物馆数量有限","verdict":"你想看的这里不够，得出城或接受线上看展。"},{"key":"TECH","name":"科技创新","score":100,"cityScore":95,"gap":5,"label":"合拍","aligned":true,"tendency":"你喜欢新东西，办事效率要高","reality":"南山科技园、坂田、坪山，硬件与互联网密度全国最高","verdict":"办事效率和新东西的密度都合你的习惯。"},{"key":"NAT","name":"自然环境","score":33,"cityScore":65,"gap":32,"label":"需要适应","aligned":false,"tendency":"你生活在室内，自然景观看得少也没关系","reality":"海岸线 260 公里，梧桐山在城内，周末去海边一小时","verdict":"自然资源比你要的多，周末不去也不亏。"},{"key":"NIGHT","name":"夜生活","score":100,"cityScore":82,"gap":18,"label":"基本合拍","aligned":true,"tendency":"你的晚上才开始，需要城市还醒着","reality":"夜宵与酒吧集中在福田、南山，营业时间长","verdict":"你想出门的时候，这里已经安静了。"},{"key":"SHOP","name":"购物消费","score":100,"cityScore":85,"gap":15,"label":"合拍","aligned":true,"tendency":"你喜欢逛，品牌和商场要齐","reality":"万象城、海岸城等大型商业体密集，品牌新","verdict":"品牌和商场密度对得上你的逛街习惯。"},{"key":"CLIM","name":"气候偏好","score":100,"cityScore":86,"gap":14,"label":"合拍","aligned":true,"tendency":"你怕冷，喜欢温暖湿润","reality":"1 月均温 15℃，夏季长，7-9 月台风影响","verdict":"气候体感合你，冬天不用硬扛。"},{"key":"COST","name":"居住成本","score":33,"cityScore":28,"gap":5,"label":"合拍","aligned":true,"tendency":"你能接受高成本，换来地段和便利","reality":"南山一居 5500 起，城中村 1800-2800，房价高","verdict":"你愿意为地段多付，这里的价格你扛得住。"},{"key":"GREEN","name":"城市绿化","score":67,"cityScore":78,"gap":11,"label":"合拍","aligned":true,"tendency":"你要树荫、公园和能走的路","reality":"公园 1200 余座，绿化覆盖率约 45%，绿道总长全国前列","verdict":"树荫、公园和绿道是日常，不是周末项目。"}],"reasons":[{"title":"节奏与成本","text":"先说每天的时间感和开销。生活节奏：平均通勤约 36 分钟，但加班普遍，写字楼夜间灯火密度高。这里节奏偏快，你也不算抗拒，勉强能对上。居住成本：南山一居 5500 起，城中村 1800-2800，房价高。你愿意为地段多付，这里的价格你扛得住。","dims":["PACE","COST"]},{"title":"吃、逛与夜晚","text":"再看日常的消费与夜晚。美食多元：移民城市，潮汕菜、湘菜、川菜与东南亚菜并存，本地菜薄。你想吃的这里给不全，得降低预期或自己找。购物消费：万象城、海岸城等大型商业体密集，品牌新。品牌和商场密度对得上你的逛街习惯。夜生活：夜宵与酒吧集中在福田、南山，营业时间长。你想出门的时候，这里已经安静了。","dims":["FOOD","SHOP","NIGHT"]},{"title":"文化、自然与绿地","text":"然后是能走能看的部分。文化历史：历史短，南头古城、大鹏所城规模小，博物馆数量有限。你想看的这里不够，得出城或接受线上看展。自然环境：海岸线 260 公里，梧桐山在城内，周末去海边一小时。自然资源比你要的多，周末不去也不亏。城市绿化：公园 1200 余座，绿化覆盖率约 45%，绿道总长全国前列。树荫、公园和绿道是日常，不是周末项目。","dims":["CULT","NAT","GREEN"]},{"title":"科技与气候","text":"最后是效率与体感。科技创新：南山科技园、坂田、坪山，硬件与互联网密度全国最高。办事效率和新东西的密度都合你的习惯。气候偏好：1 月均温 15℃，夏季长，7-9 月台风影响。气候体感合你，冬天不用硬扛。","dims":["TECH","CLIM"]}],"tradeoffs":["房价与房租仅次于北京上海","城市年轻，文化沉淀少"],"secondary":[{"city":"上海","pct":84,"conclusion":"上海：把丰富度做到极致，但要用房租、通勤和拥挤去换。","reason":"和深圳相比，历史文博更密、商业更发达，但山水要跑远。"},{"city":"武汉","pct":79,"conclusion":"武汉：江湖气足、价格温和，夏天冬天都不好过。","reason":"和深圳相比，生活成本更低、历史文博更密，但科技氛围淡一些。"},{"city":"杭州","pct":79,"conclusion":"杭州：能卷，但西湖和绿道把生活留住了。","reason":"和深圳相比，历史文博更密、更慢，但更干冷。"}],"reverse":{"city":"西宁","pct":45,"why":"生活节奏：慢，高原城市节奏（这里比你要的过头）气候偏好：夏季凉爽，冬季干冷，日照强（这里比你想要的弱）","alternatives":[{"city":"广州","pct":70,"why":"和西宁相比，更暖湿、夜生活更旺，但更快、更赶。"},{"city":"北京","pct":70,"why":"和西宁相比，科技感更强、历史文博更密，但更快、更赶。"}]},"theoryPanel":[{"title":"城市规模决定选择的数量","text":"城市越大，餐饮、展览、演出、夜宵的种类越多；但同样的丰富度，也意味着更长的通勤和更高的房租。丰富和松弛很少同时免费。"},{"title":"气候是最难改的变量","text":"气候无法靠个人努力调整。冬季日照、夏季湿度、雨季长度，会长期影响睡眠、情绪和出门频率，是选城时最值得当硬指标的一项。"},{"title":"绿地与通勤决定日常松弛","text":"绿地率、公园密度、平均通勤时间，决定散步和发呆是日常还是周末特权。它们不显眼，却最直接影响每天的状态。"},{"title":"居住成本决定选择权","text":"成本低的城市，意味着你可以接受薪水更低但更喜欢的工作、更长的空窗期。成本高则要求收入持续向上，选择会被压缩。"}],"boundary":["题目为自编，未做心理测量学标准化检验；维度分是偏好刻度，不是能力或人格测评。","城市十维坐标基于公开统计与生活经验的方向性整理（气候、绿地率、夜经济、餐饮多样性、历史街区与博物馆密度、消费水平等），会随年份和片区变化。","十个维度独立计分，不做相互抵消：某一维的高分不能补另一维的明显错位，错位维度会单独列出并计入扣分。","匹配度是剖面接近程度，不是概率，也不代表搬过去一定过得好。","结果不构成迁移、购房、医疗或投资建议；具体片区的房租、通勤、气候体感仍需自行核实。"],"matchNote":"十维等权独立计分，任一维差距 ≥45 会单独扣分并压低匹配度上限，不用其他维度的高分抵消。"}'::jsonb,'2026-11-19 14:01:32+08') on conflict (id) do nothing;
insert into public.results (id,data,created_at) values ('x2hhshsdn7','{"pct":82,"cityName":"上海","cityKey":"shanghai","conclusion":"你是上海型：要专业分工和秩序，也接受用收入换位置。","situation":"你现在缺的不是热情，是一份能积累的履历。","areas":["静安 · 南京西路","徐汇 · 漕河泾 / 徐家汇","浦东 · 张江 / 陆家嘴"],"vector":{"IND":100.0,"COST":0.0,"GATE":100.0,"PACE":100.0,"RISK":66.7,"FAM":0.0,"SETTLE":0.0},"dimRows":[{"key":"IND","name":"行业机会密度","score":100,"cityScore":96,"tendency":"需要岗位密集的大市场，随时能换赛道","reality":"金融、外企、消费品、生物医药、游戏分工极细，冷门专业也能找到对口岗。","verdict":"岗位密度和你的预期对得上，换方向不用换城。","label":"合拍","aligned":true},{"key":"COST","name":"起步成本","score":0,"cityScore":28,"tendency":"能接受高房租，把它当机会成本","reality":"内环一居 6500 起，外环 3500 上下；房租占收入三到四成很普遍。","verdict":"成本高，但你本来就不打算在住上省钱。","label":"基本合拍","aligned":true},{"key":"GATE","name":"进入门槛","score":100,"cityScore":94,"tendency":"愿意在硬门槛里竞争，学历和履历拿得出手","reality":"外企和金融卡学历与英语，校招看实习，很多岗位要求两到三段相关经历。","verdict":"门槛和你的准备匹配，进正门不用绕道。","label":"合拍","aligned":true},{"key":"PACE","name":"节奏与抗压","score":100,"cityScore":93,"tendency":"能扛快节奏和加班，把前几年当投入","reality":"地铁 20 条线，平均通勤约 45 分钟；加班比深圳克制，但标准和节奏更紧。","verdict":"节奏快，但你能扛，前几年能换来位置。","label":"合拍","aligned":true},{"key":"RISK","name":"风险与试错","score":67,"cityScore":72,"tendency":"敢试错，能接受空窗和转行","reality":"行业梯度完整，被裁后同城能接住；但房租不允许长时间空窗。","verdict":"试错空间和你的胆量匹配，失败一次还有退路。","label":"合拍","aligned":true},{"key":"FAM","name":"家庭牵绊","score":0,"cityScore":22,"tendency":"家庭牵绊小，可以去远一点的地方","reality":"高铁 2–4 小时覆盖长三角，对南方家庭尚可；对北方家庭偏远。","verdict":"离得远，你也不常回去，彼此都自在。","label":"基本合拍","aligned":true},{"key":"SETTLE","name":"长期定居","score":0,"cityScore":32,"tendency":"不急着定居，先看机会","reality":"落户靠积分和居转户，通常要 5–7 年；房价高，但公共服务全国前列。","verdict":"定居条件一般，不过你也不急着定居。","label":"基本合拍","aligned":true}],"reasons":["先看机会和门槛。金融、外企、消费品、生物医药、游戏分工极细，冷门专业也能找到对口岗。外企和金融卡学历与英语，校招看实习，很多岗位要求两到三段相关经历。对你来说，岗位密度和你的预期对得上，门槛和你的准备匹配。","再看成本和节奏。内环一居 6500 起，外环 3500 上下；房租占收入三到四成很普遍。地铁 20 条线，平均通勤约 45 分钟；加班比深圳克制，但标准和节奏更紧。你的情况是：成本高但你不在意，节奏快但你能扛。试错空间和你的胆量匹配，失败一次还有退路。","最后是家庭和定居。高铁 2–4 小时覆盖长三角，对南方家庭尚可；对北方家庭偏远。落户靠积分和居转户，通常要 5–7 年；房价高，但公共服务全国前列。对你来说，离得远，彼此都自在，定居条件一般，你也不急。"],"industries":[{"name":"金融与专业服务","path":"校招 / 社招","note":"卡证书和相关实习，起薪高但强度大。"},{"name":"外企与消费品","path":"社招","note":"英语面试，岗位稳定，晋升按部就班。"},{"name":"生物医药与游戏","path":"校招 / 社招","note":"张江和漕河泾集中，研发岗要求对口专业。"}],"landing":["投递方向：先投 100–300 人规模的外企和民企，岗位关键词带运营、分析、供应链。","房租区间：合租 2500–3500，单间 4000–5500，控制在税后收入 30% 以内。","落脚片区：9 号线松江段、11 号线嘉定段，或浦东 2 号线沿线。"],"costs":["房租是硬门槛：内环一居 7000 起，合租也要 3000 上下。","湿冷的冬天没有暖气，梅雨和回南天拉长不适感。","社交边界感强，热闹是城市的，孤独是自己的。"],"unfit":["预算有限、又不愿住到外环外的人","需要熟人式热络和低社交门槛的人","对湿冷和梅雨敏感的人"],"secondary":[{"city":"北京","pct":81,"conclusion":"你是北京型：要行业天花板，愿意为它多付房租和通勤。"},{"city":"深圳","pct":80,"conclusion":"你是深圳型：要速度和增量，愿意用几年高强度换一个位置。"},{"city":"杭州","pct":66,"conclusion":"你是杭州型：能卷，但不肯卷到失去生活。"}],"reverse":{"city":"沈阳","pct":50,"why":"它和你冲突最大的是「起步成本」和「家庭牵绊」：一居 1200–1800，合租 800–1200；生活成本全国最低一档。东北区域中心，省内高铁方便，父母期待就近发展的压力大。","alternatives":[{"city":"天津","why":"岗位层次更高，高铁 2 小时。"},{"city":"青岛","why":"气候更温和，制造业相近。"}]},"theoryPanel":[{"title":"城市规模溢价","text":"大城市给同岗位开出更高工资，但同时把房租、通勤和竞争强度一起抬高。经济学上把这叫规模溢价：收入涨得快，成本涨得更快。所以「去大城市」本身不是答案，关键看你的起薪能不能跑赢房租。"},{"title":"厚劳动力市场","text":"岗位越密集，人和岗位的匹配效率越高，跳槽带来的涨薪也越明显。代价是你必须持续证明自己。对刚毕业和想转行的人，这层「匹配效率」往往比城市名气更重要。"},{"title":"房租与通勤的取舍","text":"在单中心城市模型里，住得越远房租越低、通勤越长，理性人会沿着这条线找平衡点。结果页给你的房租区间，就是按「房租不超过税后收入 30%」反推的。"},{"title":"落户与公共服务","text":"落户、买房资格、子女入学和医保，决定了一座城市能不能从「打工的地方」变成「生活的地方」。如果你在长期定居这一维得分高，这一项会比薪资更影响你的选择。"}],"boundary":["结果基于你自述的偏好，而不是对你能力的测评；同样的答案，换一种人生阶段可能有不同结论。","城市数据来自公开统计与生活经验的方向性整理，房租、通勤、薪资会随区域和时间波动，具体到片区仍需自行核实。","匹配度是七维剖面的接近程度，是刻度不是概率，也不代表你在这座城市一定能成功。","测试没有覆盖婚育、健康、签证、行业周期等个人约束，这些因素可能比得分更决定你的选择。","结果不构成求职、迁移、购房或投资建议。真正做决定前，建议先用一周时间实地住一住、投几份简历试试水。"]}'::jsonb,'2026-11-19 13:25:28+08') on conflict (id) do nothing;
insert into public.results (id,data,created_at) values ('xaz4vwzg5w','{"pct":93,"cityName":"大理","cityKey":"dali","conclusion":"大理：全国最慢的一档，山水和阳光是日常，配套偏基础。","situation":"你现在要的不是一份城市榜单，而是一个能慢下来、也不用太拼命的地方。","portrait":{"text":"你要的是慢一点、出门见山见水、住得起；能接受文化资源少一点、新东西少一点。这不是旅行偏好，是你打算长期住下去时，最先受不了和最先离不开的部分。","vector":{"PACE":100,"FOOD":67,"CULT":33,"TECH":33,"NAT":100,"NIGHT":33,"SHOP":33,"CLIM":67,"COST":100,"GREEN":100},"top":[{"name":"生活节奏","score":100},{"name":"自然环境","score":100},{"name":"居住成本","score":100}],"low":[{"name":"文化历史","score":33},{"name":"科技创新","score":33}]},"vector":{"PACE":100,"FOOD":67,"CULT":33,"TECH":33,"NAT":100,"NIGHT":33,"SHOP":33,"CLIM":67,"COST":100,"GREEN":100},"dimRows":[{"key":"PACE","name":"生活节奏","score":100,"cityScore":95,"gap":5,"label":"合拍","aligned":true,"tendency":"你想慢下来，时间要能还给自己","reality":"全国最慢的一档，午后街上多是闲坐的人","verdict":"节奏对得上，你不用刻意调快或调慢。"},{"key":"FOOD","name":"美食多元","score":67,"cityScore":62,"gap":5,"label":"合拍","aligned":true,"tendency":"你把吃当成日常的重要部分，选择要多","reality":"白族菜与云南菜，选择有限但食材好","verdict":"吃的选择够你换着来，日常不会腻。"},{"key":"CULT","name":"文化历史","score":33,"cityScore":45,"gap":12,"label":"合拍","aligned":true,"tendency":"你对历史文博没什么兴趣","reality":"大理古城、崇圣寺三塔、喜洲古镇","verdict":"你对这些不执着，城市年轻也不影响你。"},{"key":"TECH","name":"科技创新","score":33,"cityScore":28,"gap":5,"label":"合拍","aligned":true,"tendency":"你对科技无感，传统方式更踏实","reality":"新东西少，远程办公的人多","verdict":"你不需要新东西，这里慢一点也无所谓。"},{"key":"NAT","name":"自然环境","score":100,"cityScore":97,"gap":3,"label":"合拍","aligned":true,"tendency":"你需要山、水、蓝天，出门就能碰到自然","reality":"苍山洱海，出门即景","verdict":"山或水在通勤范围内，出门就能换气。"},{"key":"NIGHT","name":"夜生活","score":33,"cityScore":45,"gap":12,"label":"合拍","aligned":true,"tendency":"你晚上不出门，安静更重要","reality":"人民路小酒馆，凌晨仍有人","verdict":"你睡得早，这里收摊早正好。"},{"key":"SHOP","name":"购物消费","score":33,"cityScore":38,"gap":5,"label":"合拍","aligned":true,"tendency":"你很少逛街，够用就行","reality":"商业以古城小店为主，品牌少","verdict":"你买得少，这里的商业够日常。"},{"key":"CLIM","name":"气候偏好","score":67,"cityScore":60,"gap":7,"label":"合拍","aligned":true,"tendency":"你怕冷，喜欢温暖湿润","reality":"高原季风，日照强，冬季干冷，紫外线高","verdict":"气候体感合你，冬天不用硬扛。"},{"key":"COST","name":"居住成本","score":100,"cityScore":66,"gap":34,"label":"需要适应","aligned":false,"tendency":"你要低开销，房租不能吃掉生活","reality":"古城外一居 1500-2000，开销低","verdict":"这里比你预期的贵，房租会吃掉一部分生活。"},{"key":"GREEN","name":"城市绿化","score":100,"cityScore":82,"gap":18,"label":"基本合拍","aligned":true,"tendency":"你要树荫、公园和能走的路","reality":"苍山植被与洱海湿地，覆盖率约 45%","verdict":"绿地和公园比你要的少，散步要挑地方。"}],"reasons":[{"title":"节奏与成本","text":"先说每天的时间感和开销。生活节奏：全国最慢的一档，午后街上多是闲坐的人。节奏对得上，你不用刻意调快或调慢。居住成本：古城外一居 1500-2000，开销低。这里比你预期的贵，房租会吃掉一部分生活。","dims":["PACE","COST"]},{"title":"吃、逛与夜晚","text":"再看日常的消费与夜晚。美食多元：白族菜与云南菜，选择有限但食材好。吃的选择够你换着来，日常不会腻。购物消费：商业以古城小店为主，品牌少。你买得少，这里的商业够日常。夜生活：人民路小酒馆，凌晨仍有人。你睡得早，这里收摊早正好。","dims":["FOOD","SHOP","NIGHT"]},{"title":"文化、自然与绿地","text":"然后是能走能看的部分。文化历史：大理古城、崇圣寺三塔、喜洲古镇。你对这些不执着，城市年轻也不影响你。自然环境：苍山洱海，出门即景。山或水在通勤范围内，出门就能换气。城市绿化：苍山植被与洱海湿地，覆盖率约 45%。绿地和公园比你要的少，散步要挑地方。","dims":["CULT","NAT","GREEN"]},{"title":"科技与气候","text":"最后是效率与体感。科技创新：新东西少，远程办公的人多。你不需要新东西，这里慢一点也无所谓。气候偏好：高原季风，日照强，冬季干冷，紫外线高。气候体感合你，冬天不用硬扛。","dims":["TECH","CLIM"]}],"tradeoffs":["本地产业单一，日常配套靠古城","医疗与教育配套弱"],"secondary":[{"city":"桂林","pct":92,"conclusion":"桂林：山水是最好的日常，城市配套偏基础。","reason":"和大理相比，更暖湿、吃的选择更多，但更快、更赶。"},{"city":"丽江","pct":89,"conclusion":"丽江：慢到极致，但日常便利和商业配套都很少。","reason":"和大理相比，历史文博更密、夜生活更旺，但更干冷。"},{"city":"昆明","pct":87,"conclusion":"昆明：气候这张牌全国少有对手，代价是节奏慢、城市规模小。","reason":"和大理相比，科技感更强、商业更发达，但更快、更赶。"}],"reverse":{"city":"上海","pct":44,"why":"居住成本：内环一居 6000 起，房租收入比长期偏高（这里比你想要的更贵）自然环境：临江临海但地势平，最近的山水在 1.5 小时车程外（这里比你想要的少）","alternatives":[{"city":"海口","pct":86,"why":"和上海相比，更慢、自然更近，但科技氛围淡一些。"},{"city":"贵阳","pct":85,"why":"和上海相比，生活成本更低、自然更近，但逛街选择少。"}]},"theoryPanel":[{"title":"城市规模决定选择的数量","text":"城市越大，餐饮、展览、演出、夜宵的种类越多；但同样的丰富度，也意味着更长的通勤和更高的房租。丰富和松弛很少同时免费。"},{"title":"气候是最难改的变量","text":"气候无法靠个人努力调整。冬季日照、夏季湿度、雨季长度，会长期影响睡眠、情绪和出门频率，是选城时最值得当硬指标的一项。"},{"title":"绿地与通勤决定日常松弛","text":"绿地率、公园密度、平均通勤时间，决定散步和发呆是日常还是周末特权。它们不显眼，却最直接影响每天的状态。"},{"title":"居住成本决定选择权","text":"成本低的城市，意味着你可以接受薪水更低但更喜欢的工作、更长的空窗期。成本高则要求收入持续向上，选择会被压缩。"}],"boundary":["题目为自编，未做心理测量学标准化检验；维度分是偏好刻度，不是能力或人格测评。","城市十维坐标基于公开统计与生活经验的方向性整理（气候、绿地率、夜经济、餐饮多样性、历史街区与博物馆密度、消费水平等），会随年份和片区变化。","十个维度独立计分，不做相互抵消：某一维的高分不能补另一维的明显错位，错位维度会单独列出并计入扣分。","匹配度是剖面接近程度，不是概率，也不代表搬过去一定过得好。","结果不构成迁移、购房、医疗或投资建议；具体片区的房租、通勤、气候体感仍需自行核实。"],"matchNote":"十维等权独立计分，任一维差距 ≥45 会单独扣分并压低匹配度上限，不用其他维度的高分抵消。"}'::jsonb,'2026-11-19 14:04:17+08') on conflict (id) do nothing;
insert into public.results (id,data,created_at) values ('xm5t8sjazc','{"pct":80,"typeId":1,"key":"poet","name":"凌晨便利店诗人","tagline":"城市越大，我越晚睡，也越自由。","chips":["夜行型","高刺激","便利店依赖","城市动物","一个人但不孤独"],"cities":[{"city":"上海","areas":"静安、黄浦、长宁（中山公园—愚园路）"},{"city":"深圳","areas":"南山、福田（车公庙、购物公园）"},{"city":"广州","areas":"天河、越秀（体育西、东山口）"},{"city":"杭州","areas":"拱墅、西湖区（武林、黄龙）"}],"profile":["你的一天从晚上十点开始。白天是义务，夜里才是自己的。","你能在 24 小时便利店里找到一种奇怪的归属感：关东煮的热气、收银员那句「需要袋子吗」、玻璃窗外的车流。","你怕的不是孤独，是无聊。你需要城市一直亮着，来证明你也没睡。","你的微信置顶有三个人，但你深夜真正会拨出去的，是外卖软件。"],"why":"你需要的不只是「夜生活」，而是夜间供给的密度：便利店、宵夜、深夜书店、凌晨还能打到车。这种密度只在一线城市的核心城区成立，因为它是人口密度、商业租金、夜班人力三者共同撑起来的。同时你对异质性的容忍度高——街上的人越杂，你越自在。","costs":["房租会吃掉你夜里消费的自由——你以为你在享受城市，其实在给房东打工。","睡眠债是复利的。二十六岁能扛，三十二岁开始还。","关系会变浅。深夜的便利店很温暖，但它不会记得你。"],"unfit":["冬天八点街上就空了的北方小城","需要早起、且家里有老人小孩的作息","你对「人多」的耐受其实没有自己以为的那么高"],"theoryTitle":"齐美尔的都市精神生活","theory":"齐美尔在《大都市与精神生活》里说，都市用高频刺激和货币经济塑造出一种「矜持而厌倦」的人格：你必须对太多刺激保持麻木，才能活下去。你熟悉的那种「在人群里最自在、却也最容易累」，不是性格缺陷，而是都市性的典型代价。沃斯进一步指出，规模、密度与异质性会带来匿名与次级关系——这既是你的自由，也是你深夜想找人说句话时，手机翻不出人的原因。","share":"我不是睡不着，我是在等这座城市先睡。","matchReason":"你的答卷里有两个信号特别明显：你在「文化密度」上得分很高（需要持续的文化刺激），在「夜间节律」上得分很高（越晚越清醒，夜里需要城市还开着）。上海恰好在这两件事上同时给出了回应——每周都有演出和展览，凌晨两点还有便利店和夜班车。城市用密度喂养你，也用密度消耗你——这是同一件事。。所以它未必是「最好的城市」，但它和你咬合得最紧。","cityName":"上海","night":{"label":"夜行动物","modifier":"服务依赖型","prescription":"你的安全感来自「随时能点到」。外卖覆盖率和便利店密度，比房租更值得你研究。"},"vector":{"N":97.2,"P":54.2,"O":100.0,"C":25.0,"K":100.0,"S":66.7,"M":66.7},"secondary":[{"name":"双城候鸟","pct":79},{"name":"新一线性价比信徒","pct":75}],"reverse":{"name":"森林边早睡者","pct":55,"city":"丽水"},"migratory":false,"migratoryType":null,"theoryPanel":[{"title":"人-环境匹配（P-E Fit）","body":"行为是人与环境交互的函数。本测试只测「需求-供给」匹配：七个维度是七种需求，城市原型是七种供给组合。匹配度描述的是「像不像」，不是「会不会幸福」。"},{"title":"恢复性环境理论（ART）","body":"自然环境的「离开感、柔和魅力、范围感、兼容性」能恢复被城市消耗的定向注意力。它解释了为什么有人住得越偏反而越好。"},{"title":"通勤悖论","body":"人们系统性低估长通勤对幸福的侵蚀，且事后补偿往往不足。中国主要城市通勤监测报告也显示，极端通勤比重在城市间差异显著。"},{"title":"都市社会学","body":"齐美尔讲都市刺激与倦怠，沃斯讲规模、密度与异质性带来的匿名，费孝通讲熟人社会与差序格局，项飙讲「附近的消失」。"},{"title":"气候与情绪","body":"季节性情感障碍（SAD）与光照时长相关；湿热、干燥与室内热舒适也真实影响睡眠与情绪。气候不是矫情，是身体。"},{"title":"生活方式迁移","body":"为生活方式而非工作迁移，是真实且增长中的现象。它带来自由，也带来身份感与成本的长期拉扯。"}],"boundary":["自报偏好不等于真实适应：结果反映你「此刻的想象」，不反映长期适应。","适应力被低估：搬家 6–12 个月后情绪常回弹，无论去哪。","百分比不是概率：它是剖面相似度刻度，不是「87% 的人会幸福」。","生态谬误：同城不同区的差异，可能大于城市之间。","硬约束未纳入：户籍、家庭、行业、健康、婚育、房贷，往往比城市气质更能决定结果。","样本与工具偏差：自编题目，未做心理测量学标准化检验。"]}'::jsonb,'2026-11-19 13:03:15+08') on conflict (id) do nothing;
insert into public.sessions (id,code,created_at,submitted_at,result_id)
